/* SIPAKATAU Interactive UX demo. No actual networking, authentication, messages or AI calls.
 * All persistent data is SYNTHETIC and stored only in this browser's localStorage. */
(()=>{'use strict';
const D=window.SIP_DATA;const KEY='sipakatau.demo.v1';const app=document.getElementById('app');
const defaults=()=>({cases:structuredClone(D.cases),categories:structuredClone(D.categories),role:null,operatorCategory:'K03',settings:{aiEnabled:false,waEnabled:true,alerts:true,protectedDefault:true,limitAI:100000,limitWA:500000,backupStatus:'BELUM DIUJI',geminiGate:'BELUM DISETUJUI'},audit:[{action:'Dataset fiktif disiapkan',at:'2026-09-19T08:00:00Z',actor:'Sistem Demo'}],outbox:[],eventIds:[],waChat:[],selectedTab:'summary',lastTicket:null,requirementsDraft:{submitterName:'',position:'',unit:'',email:'',phone:'',officialWaStatus:'AVAILABLE',officialWa:'',serviceName:'',serviceUnit:'',serviceHours:'',afterHours:'NEXT_DAY',admins:[{name:'',position:'',unit:'',email:'',phone:'',role:'PRIMARY'}],serviceChanges:'',newServices:'',specialNeeds:[],ack:false,step:0,submittedId:''},lastRequirement:null,formDraft:{type:'COMPLAINT',category:'UNKNOWN',level:'UNKNOWN',privacy:'PROTECTED',school:'',name:'',wa:'',description:'',district:'',emergency:false,adult:false,ack:false,child:false},step:0,page:1,filter:{search:'',category:'ALL',status:'ALL',channel:'ALL'},cost:{n:500,wa:60,service:1,utility:0,auth:0,marketing:0,kirim:25000,free:1000,serviceRate:356.65,utilityRate:356.65,authRate:0,marketingRate:586.33,aiEligible:80,aiCalls:1,tin:1500,tout:300,pin:0.10,pout:0.40,fx:16000,backend:100000,storage:50000,backup:100000,reserve:15,tax:0}});
let state;try{let saved=JSON.parse(localStorage.getItem(KEY)||'null');state=saved&&Array.isArray(saved.cases)?{...defaults(),...saved}:defaults()}catch{state=defaults()};
const ephemeral={toast:'',menuOpen:false,trackResult:null,chatText:'',wizardError:'',pageTab:'summary',chatScenario:'',costMode:'assumption'};
function persist(){try{localStorage.setItem(KEY,JSON.stringify(state))}catch(e){console.warn('Penyimpanan lokal tidak tersedia untuk demo.')}}
function esc(x){return String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function fmt(n){return Math.round(Number(n)||0).toLocaleString('id-ID')}function rup(n){return 'Rp'+fmt(n)}function date(s){if(!s)return '—';let d=new Date(s);return isNaN(+d)?'—':d.toLocaleDateString('id-ID',{day:'2-digit',month:'short',year:'numeric',timeZone:'Asia/Makassar'})}function now(){return new Date().toISOString()}function id(){return (crypto.randomUUID?crypto.randomUUID():'demo-'+Math.random().toString(36).slice(2))}function todayTime(){return new Date().toLocaleString('id-ID',{timeZone:'Asia/Makassar',day:'2-digit',month:'short',hour:'2-digit',minute:'2-digit'})}function cat(k){return state.categories.find(c=>c.id===k)||{id:'UNKNOWN',name:'Kategori belum dipastikan',owner:'Operator Pusat',primary:'Operator Pusat'}}function school(k){return D.schools.find(x=>x.id===k)||{name:'Belum diketahui',level:'UNKNOWN'}}function label(s){return D.statuses[s]||s}function pl(n){return n==='CRITICAL'?'Kritis':n==='HIGH'?'Tinggi':'Normal'}function privacy(p){return p==='PROTECTED'?'Identitas terlindungi':p==='NO_ID_FORM'?'Tanpa identitas':'Terbatas'}function badge(t,kind='gray'){return `<span class="pill ${kind}">${esc(t)}</span>`}function priorityTag(v){return badge(pl(v),v==='CRITICAL'?'red':v==='HIGH'?'orange':'green')}function statusTag(s){let kinds={ESCALATED:'red',NEEDS_INFO:'orange',WAITING_EXTERNAL:'orange',RECEIVED:'blue',TRIAGE:'orange',CLOSED:'green',RESOLVED:'green'};return badge(label(s),kinds[s]||'gray')}function escAttr(v){return esc(v)}
function toast(msg){ephemeral.toast=msg;let el=document.createElement('div');el.className='toast';el.setAttribute('role','status');el.textContent=msg;document.querySelectorAll('.toast').forEach(n=>n.remove());document.body.appendChild(el);setTimeout(()=>el.remove(),4400)}
function audit(action,actor='Sistem Demo'){state.audit.unshift({action,actor,at:now()});state.audit=state.audit.slice(0,150)}function caseEvent(c,action,actor='Petugas demo'){c.history.unshift({action,by:actor,at:now()});c.updated=now();audit(`${c.ticket}: ${action}`,actor)}function go(path){location.hash='#'+path}function route(){return decodeURIComponent((location.hash||'#/').slice(1)).split('?')[0]||'/'}function isStaff(path=route()){return path.startsWith('/dashboard')}function staffAccessible(){return !!state.role}function role(){return state.role||'OPERATOR_PUSAT'}function canBrowse(c){if(role()==='SUPER_ADMIN'||role()==='PIMPINAN')return false;if(role()==='PERLINDUNGAN')return c.category==='K02'||(c.secondary||[]).includes('K02');if(role()==='OPERATOR_KATEGORI')return c.category===state.operatorCategory&&c.owner==='Operator '+state.operatorCategory;return true}function casesVisible(){return state.cases.filter(canBrowse)}function canReadCase(c){return role()==='SUPER_ADMIN'||role()==='PIMPINAN'?false:canBrowse(c)}function canChange(c){return canReadCase(c)&&role()!=='PIMPINAN'&&role()!=='SUPER_ADMIN'}function isSpecial(c){return c.category==='K02'||c.privacy==='PROTECTED'||c.priority==='CRITICAL'}function view(){render();requestAnimationFrame(()=>{const main=document.getElementById('main');if(main)main.focus({preventScroll:true})})}function titlebar(t,desc='',right=''){return `<div class="panel-title"><div><h2>${esc(t)}</h2>${desc?`<p>${esc(desc)}</p>`:''}</div>${right}</div>`}
function header(){let path=route();return `<div class="demo-band">DEMO INTERAKTIF • SELURUH DATA FIKTIF • TIDAK TERHUBUNG DENGAN LAYANAN PEMERINTAH, KIRIMDEV, GEMINI, ATAU FIREBASE</div><header class="site-header"><a href="#/" class="brand" aria-label="Beranda SIPAKATAU"><img src="assets/logo-horizontal.png" alt="SIPAKATAU — Sistem Pengaduan Pendidikan Terpadu"></a><nav aria-label="Navigasi utama"><a href="#/" class="${path==='/'?'current':''}">Beranda</a><a href="#/pengaduan" class="${path==='/pengaduan'?'current':''}">Buat Pengaduan</a><a href="#/lacak" class="${path==='/lacak'?'current':''}">Lacak Tiket</a><a class="optional" href="#/panduan">Panduan</a><a class="btn primary tiny" href="#/login">Demo Petugas ↗</a></nav></header>`}
function footer(){return `<footer class="footer"><div class="container foot-grid"><div><div class="footer-logos" aria-label="Identitas Kabupaten Pinrang dan Kementerian Pendidikan Dasar dan Menengah"><img src="logo/pinrang.png" alt="Lambang Kabupaten Pinrang"><img src="logo/dikbud.webp" alt="Logo Kementerian Pendidikan Dasar dan Menengah"></div><p>Prototipe pelayanan pengaduan pendidikan untuk cakupan PAUD, SD, SMP serta pendidikan nonformal/informal sesuai kewenangan Kabupaten Pinrang. Semua contoh merupakan simulasi.</p></div><div><strong>Informasi</strong><a href="#/panduan">Panduan dan FAQ</a><a href="#/aksesibilitas">Aksesibilitas</a><a href="#/privasi">Privasi demonstrasi</a><a href="#/bantuan-anak">Jalur perlindungan</a></div><div><strong>Jelajahi</strong><a href="#/pengaduan">Ajukan pengaduan</a><a href="#/lacak">Lacak pengaduan</a><a href="#/login">Dashboard demo</a><p>Versi UI demo 1.0 • September 2026</p></div></div></footer>`}
function publicWrap(content){return `${header()}<main id="main" tabindex="-1" class="public-main">${content}</main>${footer()}`}
function home(){return publicWrap(`<section class="hero"><div class="container hero-grid"><div><span class="eyebrow">Dinas Pendidikan Kabupaten Pinrang • Rancangan digital</span><h1>Suara Anda, <em>pendidikan yang lebih baik.</em></h1><p>Satu pintu pengaduan untuk PAUD, SD, SMP, dan pendidikan nonformal/informal. Ceritakan masalah melalui WhatsApp atau formulir online, terima tiket, lalu pantau tindak lanjutnya.</p><div class="actions"><a class="btn primary" href="#/pengaduan">✍ Ajukan pengaduan</a><a class="btn" href="#/lacak">⌕ Lacak pengaduan</a><a class="btn ghost" href="#/demo-whatsapp">☏ Simulasi WhatsApp</a></div><div class="hero-note">Tanpa NIK wajib • Privasi dapat dipilih • Respons melalui petugas berwenang</div></div><div class="hero-visual"><div class="hero-float"><strong>17 kategori layanan</strong>Satu pusat pengelolaan</div><div class="mock-phone"><div class="notch"></div><div class="phone-top"><img src="assets/logo-horizontal.png" alt="Logo SIPAKATAU"><p>Selamat datang. Ada masalah pendidikan yang ingin disampaikan?</p></div><div class="phone-line">Pengaduan pendidikan <b>→</b></div><div class="phone-line">Pantau status tiket <b>→</b></div><div class="phone-line">Layanan inklusif <b>→</b></div><div class="phone-cta">Mulai pengaduan</div></div></div></div></section><section class="section"><div class="container"><span class="eyebrow">Layanan terpusat</span><h2>Lebih mudah bagi masyarakat, lebih tertata bagi dinas.</h2><p class="section-desc">SIPAKATAU tidak meminta masyarakat memahami struktur organisasi. Laporan masuk ke sistem yang sama, lalu ditindaklanjuti menurut kewenangan yang telah ditentukan.</p><div class="feature-grid"><div class="card"><span class="iconbox">☏</span><h3>Dua kanal familiar</h3><p>WhatsApp melalui Kirimdev dan formulir yang nyaman digunakan melalui ponsel.</p><a href="#/demo-whatsapp">Coba alur WhatsApp →</a></div><div class="card"><span class="iconbox teal">◎</span><h3>Satu tiket, satu riwayat</h3><p>Status, disposisi, tanggapan, dan penyelesaian terhubung dalam satu nomor tiket.</p><a href="#/lacak">Coba pelacakan →</a></div><div class="card"><span class="iconbox orange">▥</span><h3>Pemantauan transparan</h3><p>Operator menangani kasus berdasarkan penugasan. Pimpinan melihat ringkasan sesuai hak akses.</p><a href="#/login">Jelajahi dashboard →</a></div></div></div></section><section class="section soft"><div class="container"><span class="eyebrow">Cara kerja</span><h2>Empat langkah yang mudah dipahami</h2><div class="step-row">${[['1','Ceritakan masalah','Pilih kategori atau biarkan petugas membantu.'],['2','Dapatkan tiket','Sistem mencatat laporan tanpa menunggu AI.'],['3','Ditangani operator','Laporan masuk ke penanggung jawab sesuai kewenangan.'],['4','Pantau hasilnya','Periksa progres, kirim tambahan, dan ajukan keberatan bila relevan.']].map(s=>`<div class="step"><div class="step-n">${s[0]}</div><strong>${s[1]}</strong><p>${s[2]}</p></div>`).join('')}</div></div></section><section class="section"><div class="container"><span class="eyebrow">Cakupan Kabupaten</span><h2>17 kategori pengaduan</h2><p class="section-desc">Kategori dapat dipilih langsung. Jika belum tahu, gunakan opsi “Belum tahu” pada formulir dan laporan masuk ke triase operator pusat.</p><div class="catalogue">${state.categories.map(x=>`<a href="#/pengaduan" class="cat-tile" data-category-link="${x.id}"><span class="cat-num">${x.id.slice(1)}</span><span>${esc(x.name)}<small>${esc(x.owner)}</small></span></a>`).join('')}</div></div></section><section class="section soft"><div class="container grid-two"><div><span class="eyebrow">Perlindungan masyarakat</span><h2>Laporan sensitif ditangani secara khusus.</h2><p class="section-desc">Pilih identitas terlindungi atau gunakan formulir tanpa identitas. Anak yang membutuhkan bantuan keselamatan tidak boleh terhambat prosedur registrasi dewasa.</p><div class="actions"><a class="btn primary" href="#/pengaduan">Lapor aman</a><a class="btn" href="#/bantuan-anak">Informasi perlindungan</a></div></div><div class="card"><h3>Komitmen desain</h3><div class="stack"><div>✓ Tidak mewajibkan NIK untuk laporan umum</div><div>✓ Pseudonim pada antrean operator kategori</div><div>✓ Pelacakan dengan token rahasia</div><div>✓ Jalur eskalasi tanpa menunggu AI</div><div>✓ Layanan aksesibel bagi penyandang disabilitas</div></div></div></div></section>`)}
function catOptions(value='UNKNOWN'){return `<option value="UNKNOWN" ${value==='UNKNOWN'?'selected':''}>Saya belum tahu kategorinya</option>`+state.categories.map(c=>`<option value="${c.id}" ${value===c.id?'selected':''}>${c.id} — ${esc(c.name)}</option>`).join('')}
function wizard(){let f=state.formDraft,s=state.step;if(state.lastTicket&&s===4){let c=state.cases.find(x=>x.ticket===state.lastTicket);return publicWrap(`<div class="container page-wrap"><div class="result-box" role="status"><div style="font-size:38px">✓</div><span class="eyebrow">Pengaduan simulasi berhasil dicatat</span><h1>Nomor tiket Anda</h1><strong>${esc(c?.ticket||'')}</strong><p>Simpan nomor tiket dan kode rahasia berikut. Demo menyimpannya di browser ini saja, bukan di server pemerintah.</p><div><code>${esc(c?.tracking||'')}</code></div><p>Mode privasi: ${esc(privacy(c?.privacy))}. Tidak ada WhatsApp sungguhan yang dikirim.</p><div class="actions" style="justify-content:center"><button class="btn primary" data-action="copy-tracking">Salin tiket dan kode</button><button class="btn" data-action="track-created">Lacak sekarang</button><button class="btn ghost" data-action="new-complaint">Buat laporan lain</button></div></div></div>`)}
let sections=[`<div class="form-grid"><div class="field"><label for="f-type">Jenis layanan</label><select id="f-type" data-draft="type"><option value="COMPLAINT" ${f.type==='COMPLAINT'?'selected':''}>Pengaduan</option><option value="ASPIRATION" ${f.type==='ASPIRATION'?'selected':''}>Aspirasi/saran</option><option value="INFO" ${f.type==='INFO'?'selected':''}>Permintaan informasi</option></select></div><div class="field"><label for="f-category">Kategori permasalahan</label><select id="f-category" data-draft="category">${catOptions(f.category)}</select></div><div class="field"><label for="f-level">Jenjang pendidikan</label><select id="f-level" data-draft="level">${['UNKNOWN','PAUD','SD','SMP','NONFORMAL'].map(x=>`<option value="${x}" ${f.level===x?'selected':''}>${x==='UNKNOWN'?'Belum diketahui':x==='NONFORMAL'?'Nonformal / informal':x}</option>`).join('')}</select></div><div class="field"><label for="f-school">Nama sekolah (opsional)</label><input id="f-school" maxlength="120" placeholder="Nama sekolah jika diketahui" data-draft="school" value="${escAttr(f.school)}"><small>Jangan memasukkan nama asli atau data anak dalam demo.</small></div></div>`,
`<div class="form-grid"><div class="field full"><label for="f-description">Ceritakan persoalan <span class="muted">*</span></label><textarea id="f-description" data-draft="description" maxlength="2500" placeholder="Tuliskan kronologi menggunakan DATA REKAAN untuk demo ini...">${esc(f.description)}</textarea><small>Harap gunakan contoh fiktif. Dalam produksi, teks asli disimpan dengan pembatasan akses.</small></div><div class="field"><label for="f-district">Kecamatan lokasi kejadian (opsional)</label><input id="f-district" data-draft="district" maxlength="100" placeholder="Contoh: Watang Sawitto" value="${escAttr(f.district)}"></div><div class="field"><label for="f-child"><span id="child-label">Masalah melibatkan anak?</span></label><select id="f-child" data-draft="child"><option value="false" ${!f.child?'selected':''}>Tidak / belum diketahui</option><option value="true" ${f.child?'selected':''}>Ya</option></select></div><div class="field full"><label class="check-row"><input type="checkbox" data-draft="emergency" ${f.emergency?'checked':''}>Ada ancaman keselamatan yang perlu segera diperhatikan (simulasi eskalasi)</label><div class="notice warning">Jika terdapat bahaya nyata, jangan menunggu respons aplikasi demo. Gunakan layanan darurat atau layanan perlindungan resmi.</div></div></div>`,
`<div class="stack"><div class="field"><label for="f-privacy">Cara melindungi identitas</label><select id="f-privacy" data-draft="privacy"><option value="PROTECTED" ${f.privacy==='PROTECTED'?'selected':''}>Identitas terlindungi (kontak hanya di area privat)</option><option value="STANDARD_RESTRICTED" ${f.privacy==='STANDARD_RESTRICTED'?'selected':''}>Terbuka terbatas kepada petugas berwenang</option><option value="NO_ID_FORM" ${f.privacy==='NO_ID_FORM'?'selected':''}>Tanpa identitas melalui formulir</option></select></div>${f.privacy==='NO_ID_FORM'?`<div class="notice success">Formulir tidak meminta nama atau nomor WA. Simpan kode pelacakan karena tidak tersedia pemulihan dengan nomor tiket saja.</div>`:`<div class="form-grid"><div class="field"><label for="f-name">Nama (opsional)</label><input id="f-name" data-draft="name" maxlength="100" value="${escAttr(f.name)}" placeholder="Nama rekaan saat uji"></div><div class="field"><label for="f-wa">Nomor WhatsApp (opsional)</label><input id="f-wa" data-draft="wa" inputmode="tel" maxlength="22" value="${escAttr(f.wa)}" placeholder="Jangan isi nomor asli pada demo"><small>Nomor dalam demo tidak diverifikasi dan tidak digunakan untuk mengirim pesan.</small></div></div>`}<div class="notice">Unggah bukti: rancangan UI saja. Demo tidak mengirim ataupun menyimpan file nyata. Pada produksi diperlukan validasi MIME, malware scan, bucket privat, batas 5 MB per berkas dan 15 MB per kasus sebagai asumsi awal.</div></div>`,
`<div class="stack"><h3>Periksa pengaduan sebelum mengirim</h3><div class="kvs"><span>Jenis layanan</span><span>${esc(f.type)}</span></div><div class="kvs"><span>Kategori</span><span>${esc(cat(f.category).name)}</span></div><div class="kvs"><span>Jenjang</span><span>${esc(f.level)}</span></div><div class="kvs"><span>Lokasi</span><span>${esc(f.district||'Belum diisi')}</span></div><div class="kvs"><span>Privasi</span><span>${esc(privacy(f.privacy))}</span></div><div class="msg">${esc(f.description||'(belum ada kronologi)')}</div><label class="check-row"><input type="checkbox" data-draft="adult" ${f.adult?'checked':''}>Saya menyatakan berusia sekurang-kurangnya 18 tahun dan/atau melaporkan sebagai orang dewasa yang berwenang. Untuk informasi keselamatan anak, gunakan jalur khusus di bawah.</label><label class="check-row"><input type="checkbox" data-draft="ack" ${f.ack?'checked':''}>Saya memahami ini hanya demonstrasi, bukan pengaduan resmi dan seluruh data yang dimasukkan harus fiktif.</label><div class="notice warning">Pengecualian untuk informasi keselamatan anak: sistem produksi menerima dan mengarahkan laporan berisiko tanpa memaksakan registrasi 18+. Demo menyediakan pilihan "ancaman keselamatan" pada langkah 2.</div></div>`];
return publicWrap(`<div class="container page-wrap"><div class="page-head"><span class="eyebrow">Formulir mobile-first</span><h1 class="page-title">Ajukan pengaduan</h1><p>Empat tahap singkat. Anda tidak wajib mencantumkan NIK atau membuat akun.</p></div><div class="panel" style="max-width:850px;margin:auto"><div class="wizard-progress">${['Jenis masalah','Kronologi','Privasi','Konfirmasi'].map((t,i)=>`<div class="wizard-step ${i===s?'active':i<s?'done':''}">${i+1}. ${t}</div>`).join('')}</div>${sections[s]}${ephemeral.wizardError?`<div class="notice alert" role="alert">${esc(ephemeral.wizardError)}</div>`:''}<div class="form-nav"><button class="btn" data-action="wizard-prev" ${s===0?'disabled':''}>← Kembali</button><button class="btn primary" data-action="wizard-next">${s===3?'Kirim laporan simulasi':'Lanjut →'}</button></div></div></div>`)}
function tracking(){let c=ephemeral.trackResult;return publicWrap(`<div class="container page-wrap"><div class="page-head"><span class="eyebrow">Status layanan</span><h1 class="page-title">Lacak pengaduan</h1><p>Masukkan nomor tiket dan kode pelacakan. Nomor tiket saja tidak cukup untuk membuka status privat.</p></div><div class="grid-two"><form class="panel" id="tracking-form">${titlebar('Pencarian tiket','Tidak memerlukan akun publik')}<div class="stack"><div class="field"><label for="track-ticket">Nomor tiket</label><input id="track-ticket" name="ticket" required placeholder="SIP-2026-0001" value="${escAttr(state.lastTicket||'')}"></div><div class="field"><label for="track-secret">Kode pelacakan rahasia</label><input id="track-secret" name="secret" required placeholder="DEMO-0001-AMAN" autocomplete="off"></div><button class="btn primary full" type="submit">Periksa status</button><div class="notice">Untuk menguji alur, coba <strong>SIP-2026-0001</strong> dengan kode <strong>DEMO-0001-AMAN</strong>. Keduanya data contoh.</div></div></form><div class="panel">${c?`${titlebar('Hasil pelacakan aman',c.ticket)}<div class="chip-list">${statusTag(c.status)}${priorityTag(c.priority)}</div><h3>${esc(c.title)}</h3><p class="muted">Terakhir diperbarui ${date(c.updated)}</p><div class="timeline">${[...c.history].reverse().map(h=>`<div class="timeline-item"><strong>${esc(h.action.replace(/identitas/ig,'informasi'))}</strong>${date(h.at)}</div>`).join('')}</div><div class="actions"><button class="btn" data-action="public-update" data-id="${c.id}">Kirim informasi tambahan</button><button class="btn" data-action="public-appeal" data-id="${c.id}">Ajukan keberatan</button></div><p class="muted" style="font-size:11px">Detail internal, kontak, bukti dan identitas pihak tidak ditampilkan pada portal pelacakan.</p>`:`${titlebar('Status pengaduan','Informasi aman dan sederhana')}<div class="timeline"><div class="timeline-item"><strong>Tiket diterima</strong>Sistem mencatat laporan.</div><div class="timeline-item"><strong>Triase dan disposisi</strong>Unit yang berwenang memeriksa.</div><div class="timeline-item"><strong>Penanganan dan hasil</strong>Pelapor memperoleh informasi perkembangan.</div></div>`}</div></div></div>`)}
function guide(){return publicWrap(`<div class="container page-wrap"><div class="page-head"><span class="eyebrow">Pusat bantuan</span><h1 class="page-title">Panduan dan pertanyaan umum</h1><p>Informasi untuk memahami alur. Jawaban di sini bersifat contoh dan harus divalidasi instansi sebelum dipublikasikan.</p></div><div class="grid-two"><div class="panel">${titlebar('Pertanyaan yang sering diajukan')} ${D.faqs.map(x=>`<details class="faq-item"><summary>${esc(x[0])}</summary><p>${esc(x[1])}</p></details>`).join('')}</div><div class="panel">${titlebar('Bantuan berdasarkan kebutuhan')}<div class="stack"><a class="btn full" href="#/pengaduan">Ajukan pengaduan ↗</a><a class="btn full" href="#/lacak">Lacak tiket ↗</a><a class="btn full" href="#/bantuan-anak">Informasi keselamatan anak ↗</a><a class="btn full" href="#/aksesibilitas">Aksesibilitas ↗</a><div class="notice">Ruang lingkup awal: PAUD, SD, SMP, pendidikan nonformal/informal yang termasuk kewenangan kabupaten. Laporan di luar kewenangan memerlukan rujukan, bukan dihapus.</div></div></div></div></div>`)}
function childHelp(){return publicWrap(`<div class="container page-wrap"><div class="page-head"><span class="eyebrow">Perlindungan anak</span><h1 class="page-title">Jika keselamatan anak terancam</h1></div><div class="panel" style="max-width:870px"><div class="notice alert"><strong>Demo bukan saluran bantuan darurat.</strong> Jika ada bahaya saat ini, hubungi petugas berwenang atau layanan darurat setempat. Nomor resmi harus diverifikasi sebelum situs digunakan publik.</div><p>Pengaduan reguler dapat disampaikan orang tua atau wali dewasa. Informasi awal mengenai risiko keselamatan tetap harus dapat diterima dari guru, saksi, atau anak tanpa registrasi yang menghambat perlindungan. Petugas perlindungan khusus menilai dan merujuk berdasarkan prosedur.</p><div class="actions"><a class="btn primary" href="#/pengaduan">Coba formulir risiko (simulasi)</a><a class="btn" href="#/panduan">Panduan umum</a></div><p class="muted">Tidak ada diagnosis, identitas anak, atau berkas nyata yang diperlukan untuk menguji demo.</p></div></div>`)}
function a11y(){return publicWrap(`<div class="container page-wrap"><div class="page-head"><span class="eyebrow">Untuk semua pengguna</span><h1 class="page-title">Aksesibilitas layanan</h1></div><div class="grid-two"><div class="panel"><h3>Aksesibilitas menjadi syarat sejak desain</h3><p>Demo menggunakan label formulir, navigasi keyboard, fokus terlihat, kontras, desain responsif, dan penjelasan yang tidak mengandalkan warna saja. Target pengembangan WCAG 2.2 AA masih memerlukan audit manual.</p><div class="stack">${['Navigasi dengan keyboard dan pembaca layar','Teks terbaca saat zoom 200–400%','Input memiliki label dan bantuan kesalahan','Pilihan kanal alternatif dan bantuan operator','Tidak mewajibkan diagnosis medis untuk melapor'].map(x=>`<div>✓ ${x}</div>`).join('')}</div></div><div class="panel"><h3>Informasi layanan disabilitas</h3><p>Kategori K17 mencakup penolakan murid, kebutuhan akomodasi yang layak, aksesibilitas sarpras, ujian, informasi, dan layanan ULD bila pembentukannya telah diverifikasi.</p><a href="#/pengaduan" data-category-link="K17" class="btn primary">Coba laporan K17</a></div></div></div>`)}
function priv(){return publicWrap(`<div class="container page-wrap"><div class="page-head"><span class="eyebrow">Kebijakan demo</span><h1 class="page-title">Privasi dan penggunaan data simulasi</h1></div><div class="panel" style="max-width:900px"><p><strong>Demo ini tidak terhubung ke server.</strong> Data rekaan yang Anda masukkan disimpan di <code>localStorage</code> browser untuk menunjukkan alur dan dapat dihapus lewat Reset Demo pada dashboard. Jangan masukkan data nyata.</p><div class="notice warning">Dalam produksi, kontak privat harus disimpan terpisah dan terenkripsi, kontrol akses diterapkan backend, kebijakan retensi disahkan, serta vendor dan lokasi pemrosesan diperiksa sebelum layanan diaktifkan.</div><h3>Tiga mode privasi</h3><p>Terbuka terbatas, identitas terlindungi dari operator kategori, dan tanpa identitas melalui form. WhatsApp tidak dapat disebut anonim penuh karena nomor pengirim diketahui gateway komunikasi.</p><a class="btn" href="#/pengaduan">Coba pengaturan privasi</a></div></div>`)}
function login(){return `<div class="demo-band">SIMULASI ROLE SAJA • BUKAN AUTENTIKASI PRODUKSI • TIDAK ADA AKSES DATA NYATA</div><main id="main" tabindex="-1" class="login-wrap"><section class="login-art"><img src="assets/logo-horizontal.png" alt="SIPAKATAU"><h1>Satu pusat kendali.<br>Pelayanan lebih terarah.</h1><p>Masuk sebagai peran fiktif untuk melihat perbedaan akses, alur triase, penugasan, dan pemantauan pimpinan.</p><div>${badge('17 operator • 1 dashboard','green')}</div></section><section class="login-form"><form class="panel" id="role-login"><span class="eyebrow">Mode demonstrasi</span><h2>Masuk ke dashboard</h2><p class="muted">Pilih peran yang ingin disimulasikan. Ini bukan sistem login yang aman; autentikasi sesungguhnya harus dilakukan pada backend.</p><div class="stack"><div class="field"><label for="demo-role">Peran petugas</label><select id="demo-role" name="role">${D.roles.map(r=>`<option value="${r.id}">${esc(r.name)} — ${esc(r.description)}</option>`).join('')}</select></div><div class="field" id="role-category"><label for="demo-cat">Kategori operator (jika berperan sebagai operator kategori)</label><select name="category" id="demo-cat">${state.categories.map(c=>`<option value="${c.id}" ${c.id===state.operatorCategory?'selected':''}>${c.id} — ${esc(c.name)}</option>`).join('')}</select></div><button class="btn primary full" type="submit">Masuk sebagai peran demo →</button><a class="btn full" href="#/">← Kembali ke layanan publik</a></div><div class="notice warning">Identitas terlindungi tidak pernah tampil di data demo. Pada produksi, seluruh akses membutuhkan autentikasi kuat, MFA, dan otorisasi backend.</div></form></section></main>`}
const nav=[['OVERVIEW','/dashboard','▦','Ikhtisar'],['LAYANAN','/dashboard/inbox','▤','Kotak masuk'],['LAYANAN','/dashboard/cases','▣','Semua kasus'],['LAYANAN','/dashboard/assignments','⇄','Penugasan'],['LAYANAN','/dashboard/escalations','⚑','Prioritas & eskalasi'],['LAYANAN','/dashboard/whatsapp','☏','Simulasi WhatsApp'],['MONITORING','/dashboard/reports','▥','Laporan pimpinan'],['MONITORING','/dashboard/ai','✦','Asisten AI'],['MONITORING','/dashboard/costs','◉','Simulasi biaya'],['PENGELOLAAN','/dashboard/admin/categories','▦','17 kategori & routing'],['PENGELOLAAN','/dashboard/admin/schools','⌂','Master sekolah'],['PENGELOLAAN','/dashboard/admin/users','♙','Akun & peran'],['PENGELOLAAN','/dashboard/admin/settings','⚙','Pengaturan sistem'],['PENGELOLAAN','/dashboard/admin/backup','⇧','Backup & pemulihan'],['PENGELOLAAN','/dashboard/admin/audit','≡','Audit aktivitas']];
function navAllowed(path){if(role()==='PIMPINAN')return ['/dashboard','/dashboard/reports','/dashboard/escalations','/dashboard/costs'].includes(path);if(role()==='SUPER_ADMIN')return ['/dashboard','/dashboard/costs','/dashboard/admin/categories','/dashboard/admin/schools','/dashboard/admin/users','/dashboard/admin/settings','/dashboard/admin/backup','/dashboard/admin/audit','/dashboard/ai'].includes(path);if(role()==='OPERATOR_KATEGORI')return ['/dashboard','/dashboard/inbox','/dashboard/cases','/dashboard/assignments','/dashboard/ai'].includes(path);if(role()==='PERLINDUNGAN')return ['/dashboard','/dashboard/inbox','/dashboard/cases','/dashboard/assignments','/dashboard/escalations','/dashboard/ai'].includes(path);return ['/dashboard','/dashboard/inbox','/dashboard/cases','/dashboard/assignments','/dashboard/escalations','/dashboard/whatsapp','/dashboard/reports','/dashboard/ai'].includes(path)}
function staffShell(content){let path=route(),prev='';return `<div class="demo-band">DASHBOARD SIMULASI • SEMUA ANGKA FIKTIF • PENGUJIAN OTORISASI NYATA WAJIB DI BACKEND</div><div class="staff-shell"><aside id="sidebar" class="sidebar ${ephemeral.menuOpen?'open':''}" aria-label="Navigasi petugas"><div class="sidebar-brand"><img src="assets/logo-horizontal.png" alt="SIPAKATAU"><p>COMMAND CENTER • PINRANG</p></div><nav class="side-links">${nav.filter(x=>navAllowed(x[1])).map(([group,href,mark,name])=>{let g=prev!==group?`<div class="side-label">${group}</div>`:'';prev=group;return g+`<a href="#${href}" class="${path===href||(path.startsWith('/dashboard/cases/')&&href==='/dashboard/cases')?'active':''}"><span class="mark" aria-hidden="true">${mark}</span>${name}</a>`}).join('')}</nav><div class="side-footer"><div style="font-weight:750">SIPAKATAU DEMO V1.0</div><div style="margin:7px 0;color:#a8c2dd">Mode offline • bukan data produksi</div><button class="btn tiny full" data-action="logout">Keluar dari role</button></div></aside><div class="staff-content"><header class="topbar"><div class="topbar-left"><button class="btn tiny mobile-nav-toggle" aria-label="Buka atau tutup menu" data-action="toggle-menu">☰</button><div><div class="top-title">SIPAKATAU / Dashboard</div><small>Dinas Pendidikan Kabupaten Pinrang • Demonstrasi</small></div></div><div class="row"><span class="role-chip">${esc(D.roles.find(r=>r.id===role())?.name||role())}${role()==='OPERATOR_KATEGORI'?' • '+state.operatorCategory:''}</span><button class="btn tiny" data-action="logout">Keluar</button></div></header><main id="main" tabindex="-1" class="staff-main">${content}</main></div></div>`}
function metric(name,value,note='',kind=''){return `<div class="metric ${kind}"><small>${esc(name)}</small><strong>${esc(value)}</strong><span class="delta">${esc(note)}</span></div>`}
function staffTitle(name,desc,actions=''){return `<div class="case-header"><div><div class="eyebrow">SIPAKATAU • ${esc(role())}</div><h1>${esc(name)}</h1><p class="intro">${esc(desc)}</p></div>${actions}</div>`}
function bars(items,max){return `<div class="bars">${items.map(x=>`<div class="bar-row"><span>${esc(x[0])}</span><div class="bar-track"><div class="bar-fill" style="width:${max?Math.max(1,100*x[1]/max):0}%"></div></div><strong>${x[1]}</strong></div>`).join('')}</div>`}
function overview(){let cv=casesVisible();let all=state.cases;let isLeader=role()==='PIMPINAN',isAdmin=role()==='SUPER_ADMIN';let show=isLeader||isAdmin?all:cv;let open=show.filter(c=>!['CLOSED','RESOLVED'].includes(c.status)).length,critical=show.filter(c=>c.priority==='CRITICAL').length,closed=show.filter(c=>['CLOSED','RESOLVED'].includes(c.status)).length,late=show.filter(c=>c.status==='ESCALATED').length;let by=state.categories.map(c=>[c.id+' • '+c.name.split(' ').slice(0,2).join(' '),show.filter(x=>x.category===c.id).length]).sort((a,b)=>b[1]-a[1]).slice(0,7);return staffShell(`${staffTitle('Ikhtisar pelayanan','Dashboard berdasarkan peran. Semua statistik berasal dari kumpulan kasus simulasi, bukan statistik Pinrang.',`<div class="actions"><a class="btn" href="#/">Lihat situs publik</a>${navAllowed('/dashboard/inbox')?'<a class="btn primary" href="#/dashboard/inbox">Buka kotak masuk →</a>':''}</div>`)}<div class="dash-grid">${metric('Total kasus',fmt(show.length),'Jumlah kasus unik')}${metric('Kasus terbuka',fmt(open),'Memerlukan tindak lanjut','orange')}${metric('Kasus selesai',fmt(closed),'Status terselesaikan/ditutup','green')}${metric('Prioritas kritis',fmt(critical),'Pemeriksaan manusia wajib','red')}</div><div class="grid-two" style="margin-top:19px"><section class="panel">${titlebar('Distribusi kategori','Dihitung dari kasus unik, bukan total pesan',`<a class="btn tiny" href="#/dashboard/reports">Laporan →</a>`)}${bars(by,Math.max(...by.map(x=>x[1]),1))}</section><section class="panel">${titlebar('Antrean perlu perhatian','Laporan kritis dan kasus yang dieskalasi')}${show.filter(c=>c.priority==='CRITICAL'||c.status==='ESCALATED').slice(0,5).map(c=>`<div class="mini-log"><div class="row space"><strong>${esc(c.ticket)}</strong>${priorityTag(c.priority)}</div><span>${esc(cat(c.category).name)}</span><br><small>${esc(label(c.status))} • ${esc(c.privacy==='PROTECTED'?'Identitas terlindungi':'Akses terbatas')}</small>${canReadCase(c)?` <a href="#/dashboard/cases/${c.id}">Periksa →</a>`:''}</div>`).join('')||'<div class="empty">Tidak ada antrean prioritas.</div>'}<div class="notice warning">Data pimpinan bersifat agregat. Detail sensitif harus melalui penugasan dan dasar kewenangan.</div></section></div><div class="grid-two" style="margin-top:19px"><section class="panel">${titlebar('Status kanal dan fitur')}${[['Form online','SIMULASI AKTIF',true],['Kirimdev Cloud API','HANYA SIMULASI',false],['Gemini AI',state.settings.aiEnabled?'ON • OUTPUT DEMO':'OFF / BELUM DISETUJUI',false],['Backup & restore',state.settings.backupStatus,false]].map(x=>`<div class="kvs"><span>${x[0]}</span><span>${badge(x[1],x[2]?'green':'orange')}</span></div>`).join('')}</section><section class="panel">${titlebar('Akses cepat','Pilih alur pengujian sesuai peran')}<div class="stack">${nav.filter(x=>navAllowed(x[1])&&['/dashboard/inbox','/dashboard/cases','/dashboard/whatsapp','/dashboard/costs','/dashboard/admin/categories','/dashboard/reports'].includes(x[1])).map(x=>`<a class="btn full" href="#${x[1]}">${x[2]} ${x[3]} →</a>`).join('')}</div></section></div>`)}
function filterCases(scope='cases'){let cs=casesVisible().filter(c=>scope==='inbox'?['RECEIVED','TRIAGE','NEEDS_INFO'].includes(c.status):scope==='escalation'?c.priority==='CRITICAL'||c.status==='ESCALATED':scope==='assignments'?c.owner||c.status==='ASSIGNED':true);let f=state.filter;if(f.search){const q=f.search.toLowerCase();cs=cs.filter(c=>(c.ticket+' '+c.title+' '+cat(c.category).name+' '+school(c.school).name).toLowerCase().includes(q))}if(f.category!=='ALL')cs=cs.filter(c=>c.category===f.category);if(f.status!=='ALL')cs=cs.filter(c=>c.status===f.status);if(f.channel!=='ALL')cs=cs.filter(c=>c.channel===f.channel);return cs.sort((a,b)=>new Date(b.received)-new Date(a.received))}
function tableCases(scope='cases'){let rows=filterCases(scope),count=rows.length,per=12,pages=Math.max(1,Math.ceil(count/per));state.page=Math.min(Math.max(1,state.page),pages);let slice=rows.slice((state.page-1)*per,state.page*per);return `<div class="toolbar"><label class="sr-only" for="case-query">Cari kasus</label><input id="case-query" placeholder="Cari nomor tiket, judul, atau sekolah..." value="${escAttr(state.filter.search)}" data-filter="search"><label class="sr-only" for="case-category">Kategori</label><select id="case-category" data-filter="category"><option value="ALL">Semua kategori</option>${state.categories.map(c=>`<option value="${c.id}" ${state.filter.category===c.id?'selected':''}>${c.id} — ${esc(c.name)}</option>`).join('')}</select><label class="sr-only" for="case-status">Status</label><select id="case-status" data-filter="status"><option value="ALL">Semua status</option>${Object.entries(D.statuses).map(([k,v])=>`<option value="${k}" ${state.filter.status===k?'selected':''}>${esc(v)}</option>`).join('')}</select><label class="sr-only" for="case-channel">Kanal</label><select id="case-channel" data-filter="channel"><option value="ALL">Semua kanal</option><option value="WHATSAPP" ${state.filter.channel==='WHATSAPP'?'selected':''}>WhatsApp</option><option value="FORM" ${state.filter.channel==='FORM'?'selected':''}>Form online</option></select><button class="btn tiny" data-action="clear-filters">Reset filter</button></div><div class="table-wrap"><table class="data-table"><thead><tr><th>Tiket / perihal</th><th>Kategori</th><th>Prioritas</th><th>Status</th><th>Pemilik</th><th>Diterima</th><th>Aksi</th></tr></thead><tbody>${slice.map(c=>`<tr><td><strong>${esc(c.ticket)}</strong><small>${esc(c.title)}</small></td><td>${esc(c.category)}<br><small>${esc(cat(c.category).name)}</small></td><td>${priorityTag(c.priority)}</td><td>${statusTag(c.status)}</td><td>${esc(c.owner||'Operator Pusat / triase')}</td><td>${date(c.received)}<br><small>${c.channel==='FORM'?'Form online':'WhatsApp'}</small></td><td><a class="btn tiny" href="#/dashboard/cases/${c.id}">Lihat →</a></td></tr>`).join('')||'<tr><td colspan="7"><div class="empty"><strong>Belum ada data sesuai filter</strong>Coba ubah kategori, status, atau kata kunci.</div></td></tr>'}</tbody></table></div><div class="pagination"><span>${count?`${(state.page-1)*per+1}–${Math.min(count,state.page*per)} dari ${count}`:'0 data'} • Halaman ${state.page}/${pages}</span><div class="row"><button class="btn tiny" data-action="page-prev" ${state.page===1?'disabled':''}>← Sebelumnya</button><button class="btn tiny" data-action="page-next" ${state.page===pages?'disabled':''}>Berikutnya →</button></div></div>`}
function inbox(){return staffShell(`${staffTitle('Kotak masuk terpadu','Laporan baru, perlu triase, dan kekurangan informasi. Tidak semua chat merupakan kasus baru.',`<div class="actions"><a class="btn" href="#/dashboard/whatsapp">Simulasikan WA</a><a class="btn primary" href="#/pengaduan">Buka form publik</a></div>`)}<section class="panel">${titlebar('Antrean triase','Cari, filter, dan buka tiket untuk menetapkan operator')}${tableCases('inbox')}</section>`)}
function cases(){return staffShell(`${staffTitle('Manajemen seluruh kasus','Daftar terfilter menurut hak akses dan penugasan demo. Backend produksi harus menegakkan pembatasan yang sama.') }<section class="panel">${titlebar('Daftar kasus','Mencakup lintas kanal, status, dan kategori yang berhak dilihat')}${tableCases('cases')}</section>`)}
function assignments(){return staffShell(`${staffTitle('Penugasan dan disposisi','Satu pemilik kasus aktif, operator pengganti, dan riwayat pengalihan.')}<div class="grid-two"><div class="panel">${titlebar('Konfigurasi penanggung jawab')}${state.categories.filter(c=>role()==='OPERATOR_KATEGORI'?c.id===state.operatorCategory:true).map(c=>`<div class="mini-log"><strong>${c.id} • ${esc(c.name)}</strong><div class="muted">Utama: ${esc(c.primary)} • Cadangan: ${esc(c.backup)}</div></div>`).join('')}</div><div class="panel">${titlebar('Kasus dengan penugasan','Klik untuk memeriksa dan mengubah sesuai izin')}${filterCases('assignments').slice(0,15).map(c=>`<div class="mini-log"><div class="row space"><strong>${esc(c.ticket)}</strong>${statusTag(c.status)}</div><div>${esc(c.owner||'Belum ditetapkan')} • ${esc(cat(c.category).name)}</div><a href="#/dashboard/cases/${c.id}">Buka kasus →</a></div>`).join('')||'<div class="empty">Belum ada penugasan.</div>'}</div></div>`)}
function escalations(){let e=role()==='PIMPINAN'?state.cases.filter(c=>c.priority==='CRITICAL'||c.status==='ESCALATED'):casesVisible().filter(c=>c.priority==='CRITICAL'||c.status==='ESCALATED');return staffShell(`${staffTitle('Prioritas dan eskalasi','Kasus keselamatan segera diberi penanda. Penanda AI tidak menggantikan tindakan petugas.') }<div class="dash-grid">${metric('Kasus prioritas',e.length,'Kritis atau dieskalasi','red')}${metric('Kritis',e.filter(c=>c.priority==='CRITICAL').length,'Perlu pemeriksaan cepat','red')}${metric('Eskalasi',e.filter(c=>c.status==='ESCALATED').length,'Ke pejabat berwenang','orange')}${metric('Belum ditugaskan',e.filter(c=>!c.owner).length,'Jangan sampai terlantar','orange')}</div><div class="panel" style="margin-top:20px">${titlebar('Daftar prioritas','Pimpinan menerima rekap aman; pengaduan sensitif tidak dibuka tanpa kewenangan')}<div class="table-wrap"><table class="data-table"><thead><tr><th>Tiket</th><th>Substansi</th><th>Penanda</th><th>Status</th><th>Aksi</th></tr></thead><tbody>${e.map(c=>`<tr><td><strong>${esc(c.ticket)}</strong></td><td>${esc(cat(c.category).name)}</td><td>${priorityTag(c.priority)}</td><td>${statusTag(c.status)}</td><td>${canReadCase(c)?`<a href="#/dashboard/cases/${c.id}">Periksa →</a>`:'Ringkasan agregat saja'}</td></tr>`).join('')}</tbody></table></div></div>`)}
function caseDetail(caseId){let c=state.cases.find(x=>x.id===caseId);if(!c)return staffShell(`${staffTitle('Kasus tidak ditemukan','Nomor referensi tidak tersedia pada dataset demo.')}<a class="btn" href="#/dashboard/cases">← Kembali</a>`);if(!canReadCase(c))return staffShell(`${staffTitle('Akses kasus dibatasi','Peran ini hanya berhak melihat statistik agregat atau konfigurasi sistem.')}<div class="notice alert">DEMO PERMISSION DENIED: akses detail kasus tidak diberikan kepada ${esc(role())}. Ini simulasi UI. Backend produksi tetap wajib menolak akses langsung API atau ID.</div><a class="btn" href="#/dashboard">Kembali ke dashboard</a>`);
let tabs=[['summary','Ringkasan'],['original','Pesan asli'],['timeline','Riwayat'],['attachments','Bukti'],['assignment','Penugasan'],['response','Balasan'],['policy','Aturan & AI']];let selected=ephemeral.pageTab;let tabcontent={
summary:`${titlebar('Ringkasan pengaduan','Ringkasan AI hanyalah usulan dan bukan fakta terverifikasi')}<div class="notice warning">${c.ai?`HASIL AI SIMULASI: ${esc(c.ai.summary)} — draf, tidak boleh mengubah tuduhan menjadi fakta.`:'AI belum dijalankan pada kasus ini. Kronologi asli tetap menjadi sumber informasi.'}</div><div class="msg"><strong>Kronologi terlapor — data rekaan</strong>${esc(c.description)}</div><div class="chip-list">${badge(cat(c.category).name)}${c.secondary.map(x=>badge(cat(x).name,'orange')).join('')}${badge(privacy(c.privacy),'green')}</div>`,
original:`${titlebar('Pesan dan kronologi asli','Tidak pernah ditimpa ringkasan AI')}${c.messages.map(m=>`<div class="msg ${m.by==='internal'?'internal':''}"><strong>${esc(m.by)} • ${date(m.at)}</strong>${esc(m.text)}</div>`).join('')}`, 
timeline:`${titlebar('Jejak tindakan','Perubahan dicatat untuk peninjauan dan audit') }<div class="timeline">${c.history.map(h=>`<div class="timeline-item"><strong>${esc(h.action)}</strong>${esc(h.by)} • ${date(h.at)}</div>`).join('')}</div>`,
attachments:`${titlebar('Lampiran privat','Demo tidak menerima file nyata')}<div class="notice warning">Belum ada lampiran. Implementasi nyata: penyimpanan privat di lokasi disetujui, antivirus, validasi MIME/magic bytes, checksum SHA-256, dan akses berdasarkan penugasan.</div><button class="btn" data-action="attachments-info">Lihat spesifikasi lampiran</button>`,
assignment:`${titlebar('Kepemilikan dan routing','Jangan kirim kasus kepada pihak terlapor')}<div class="kvs"><span>Penanggung jawab</span><span>${esc(c.owner||'Belum ditugaskan')}</span></div><div class="kvs"><span>Aturan kategori</span><span>${esc(cat(c.category).owner)}</span></div><div class="kvs"><span>Operator pengganti</span><span>${esc(cat(c.category).backup)}</span></div><div class="kvs"><span>Perlu perlindungan</span><span>${isSpecial(c)?'Ya — pemeriksaan khusus':'Sesuai kebutuhan kasus'}</span></div>${role()==='OPERATOR_PUSAT'||role()==='PERLINDUNGAN'?`<form id="assign-form" class="stack" style="margin-top:16px"><div class="field"><label for="assign-category">Kategori tujuan</label><select id="assign-category" name="category">${state.categories.map(x=>`<option value="${x.id}" ${x.id===c.category?'selected':''}>${x.id} — ${esc(x.name)}</option>`).join('')}</select></div><input type="hidden" name="caseid" value="${c.id}"><button type="submit" class="btn primary">Validasi dan tetapkan operator</button></form>`:'<div class="notice">Perubahan disposisi hanya untuk operator pusat/petugas perlindungan berwenang.</div>'}`,
response:`${titlebar('Komunikasi dengan pelapor','Balasan operator melalui gateway; nomor pribadi tidak ditampilkan')}<div class="notice">${c.privacy==='PROTECTED'?'Mode terlindungi: kontak disembunyikan dari operator kategori.':'Pengiriman tetap harus melalui gateway resmi.'} Semua pengiriman pada demo hanya menambah catatan lokal.</div>${canChange(c)?`<form id="reply-form" class="stack"><input type="hidden" name="caseid" value="${c.id}"><div class="field"><label for="reply-text">Isi tanggapan (data contoh)</label><textarea id="reply-text" name="message" required maxlength="700" placeholder="Tulis tanggapan yang telah diperiksa petugas..."></textarea></div><button class="btn primary" type="submit">Simpan balasan simulasi</button></form>`:'Akses terbatas.'}<div>${c.messages.filter(x=>x.by==='petugas').map(x=>`<div class="msg"><strong>Balasan tersimpan • ${date(x.at)}</strong>${esc(x.text)}</div>`).join('')}</div>`,
policy:`${titlebar('Kebijakan pemrosesan','AI tidak menentukan hukuman, kebenaran fakta, atau penutupan kasus')}<div class="kvs"><span>Prioritas</span><span>${pl(c.priority)}</span></div><div class="kvs"><span>Mode AI</span><span>${state.settings.aiEnabled?'DEMO ONLY':'NONAKTIF'}</span></div><div class="kvs"><span>Persyaratan Gemini</span><span>${esc(state.settings.geminiGate)}</span></div><div class="kvs"><span>Aturan kategori</span><span>${esc(c.category)} / versi demo-1</span></div><div class="notice warning">Jika AI hidup di demo, hasil berasal dari fungsi deterministik lokal. Tidak ada API eksternal yang dipanggil.</div>${canChange(c)?`<button class="btn" data-action="analyze" data-id="${c.id}">✦ Analisis AI simulasi</button>`:''}`
};let transitions=[['TRIAGE','Mulai triase'],['ASSIGNED','Tandai didisposisikan'],['IN_PROGRESS','Mulai penanganan'],['NEEDS_INFO','Perlu informasi'],['WAITING_EXTERNAL','Tunggu instansi terkait'],['ESCALATED','Eskalasi'],['RESOLUTION_REVIEW','Ajukan verifikasi hasil'],['RESOLVED','Setujui hasil'],['CLOSED','Tutup kasus'],['REOPENED','Buka kembali']];let allowed=transitions.filter(([status])=>{if(status==='CLOSED')return c.status==='RESOLVED'&&(role()==='OPERATOR_PUSAT'||role()==='PERLINDUNGAN');if(status==='RESOLVED')return c.status==='RESOLUTION_REVIEW'&&(role()==='OPERATOR_PUSAT'||role()==='PERLINDUNGAN');if(status==='RESOLUTION_REVIEW')return c.status==='IN_PROGRESS'||c.status==='WAITING_EXTERNAL';if(status==='REOPENED')return c.status==='CLOSED';if(status==='TRIAGE')return c.status==='RECEIVED';if(status==='ASSIGNED')return ['TRIAGE','NEEDS_INFO','REOPENED'].includes(c.status);if(status==='IN_PROGRESS')return ['ASSIGNED','NEEDS_INFO','REOPENED'].includes(c.status);if(status==='NEEDS_INFO')return ['TRIAGE','IN_PROGRESS'].includes(c.status);if(status==='WAITING_EXTERNAL')return c.status==='IN_PROGRESS';if(status==='ESCALATED')return !['CLOSED','RESOLVED'].includes(c.status);return false});
return staffShell(`<div class="case-header"><div><a href="#/dashboard/cases" class="muted" style="font-size:12px">← Kembali ke kasus</a><h1>${esc(c.ticket)}</h1><p class="intro">${esc(c.title)}</p><div class="chip-list">${statusTag(c.status)}${priorityTag(c.priority)}${badge(privacy(c.privacy),'green')}${badge(c.channel==='FORM'?'Form Online':'WhatsApp')}</div></div><div class="actions"><button class="btn" data-action="copy-ticket" data-id="${c.id}">Salin tiket</button>${canChange(c)?`<button class="btn orange" data-action="case-escalate" data-id="${c.id}">⚑ Eskalasi</button>`:''}</div></div><div class="case-layout"><section class="panel"><div class="tabs" role="tablist" aria-label="Informasi kasus">${tabs.map(([key,label])=>`<button role="tab" aria-selected="${selected===key}" class="${selected===key?'active':''}" data-tab="${key}">${label}</button>`).join('')}</div>${tabcontent[selected]||tabcontent.summary}</section><aside class="stack"><div class="panel">${titlebar('Informasi kasus')}<div class="kvs"><span>Kategori</span><span>${esc(cat(c.category).name)}</span></div><div class="kvs"><span>Satuan pendidikan</span><span>${esc(school(c.school).name)}</span></div><div class="kvs"><span>Jenjang</span><span>${esc(c.level)}</span></div><div class="kvs"><span>Operator aktif</span><span>${esc(c.owner||'Operator pusat (triase)')}</span></div><div class="kvs"><span>Diterima</span><span>${date(c.received)}</span></div><div class="kvs"><span>Deadline contoh</span><span>${date(c.deadline)}</span></div><div class="kvs"><span>Identitas pelapor</span><span>${badge('TIDAK DITAMPILKAN','green')}</span></div></div><div class="panel">${titlebar('Aksi penanganan','Tindakan hanya tersedia menurut peran dan status')}${canChange(c)?`<div class="stack">${allowed.map(([s,label])=>`<button class="btn full ${s==='ESCALATED'?'danger':s==='RESOLVED'?'primary':''}" data-action="transition" data-status="${s}" data-id="${c.id}">${esc(label)}</button>`).join('')||'<div class="muted">Tidak ada transisi yang tersedia untuk status ini.</div>'}<button class="btn full" data-action="open-tab" data-tab="response">Tulis tanggapan →</button></div>`:'<div class="notice">Tidak ada kewenangan mengubah status.</div>'}</div><div class="panel"><h3>Jejak perlindungan</h3><p class="muted" style="font-size:12px">Mode simulasi hanya menampilkan data sintetis dan tidak memberikan akses pembukaan identitas.</p></div></aside></div>`)}
function simulatedWhatsApp(){let chat=state.waChat;return staffShell(`${staffTitle('Simulasi WhatsApp','Mensimulasikan webhook Kirimdev, tiket, duplikasi event, dan outbox. Tidak ada pesan sungguhan.',`<button class="btn" data-action="wa-reset">Kosongkan percakapan demo</button>`)}<div class="grid-two"><div class="panel">${titlebar('Percakapan WhatsApp • simulasi','Contoh nomor tidak disimpan atau ditampilkan')}<div class="fake-chat"><div class="chat-top">☏ SIPAKATAU • Pesan masuk demo</div>${chat.length?chat.map(m=>`<div class="bubble ${m.by==='sistem'?'sent':''}">${esc(m.text)}<small>${esc(m.by)} • ${esc(m.at)}</small></div>`).join(''):`<div class="bubble">Selamat datang di SIPAKATAU. Silakan sampaikan masalah pendidikan. <small>Sistem demo</small></div>`}</div><form id="wa-form" class="stack" style="margin-top:13px"><div class="field"><label for="wa-text">Pesan simulasi masyarakat</label><textarea id="wa-text" name="text" maxlength="1200" placeholder="Gunakan contoh rekaan, bukan nama atau identitas nyata...">${esc(ephemeral.chatText)}</textarea></div><div class="row" style="flex-wrap:wrap"><button type="submit" class="btn primary">Kirim pesan simulasi</button><button type="button" class="btn" data-action="wa-canned" data-scenario="safety">Contoh bahaya bangunan</button><button type="button" class="btn" data-action="wa-canned" data-scenario="disability">Contoh layanan disabilitas</button></div></form></div><div class="stack"><div class="panel">${titlebar('Alur yang terjadi','Semua langkah disimulasikan di JavaScript lokal')}<div class="timeline">${[['1. Webhook diterima','Event ID diperiksa'],['2. Data dicatat','Idempotensi mencegah tiket ganda'],['3. Tiket dibuat','Sebelum AI dipanggil'],['4. Rules engine','Kategori dan indikator keselamatan'],['5. Outbox','Pesan tindak lanjut tidak dikirim nyata']].map(x=>`<div class="timeline-item"><strong>${x[0]}</strong>${x[1]}</div>`).join('')}</div></div><div class="panel">${titlebar('Kontrol integrasi demo')}<div class="kvs"><span>Webhook aktif</span><span>${badge('SIMULASI','orange')}</span></div><div class="kvs"><span>Event unik diterima</span><span>${state.eventIds.length}</span></div><div class="kvs"><span>Outbox simulasi</span><span>${state.outbox.length} pesan</span></div><div class="actions"><button class="btn" data-action="wa-replay">Uji replay event terakhir</button><button class="btn" data-action="wa-delivery">Uji status delivered</button></div><div class="notice warning">Tidak ada kunci Kirimdev, tanda tangan HMAC, atau pengiriman sungguhan. Dokumen 09 menjelaskan integrasi produksi.</div></div></div></div>`)}
function reports(){let all=role()==='PIMPINAN'?state.cases:casesVisible();let total=all.length;let levels=['PAUD','SD','SMP','NONFORMAL','UNKNOWN'].map(x=>[x,all.filter(c=>c.level===x).length]);let channel=[['WhatsApp',all.filter(c=>c.channel==='WHATSAPP').length],['Form online',all.filter(c=>c.channel==='FORM').length]];let by=state.categories.map(c=>[c.id+' '+c.name.split(' ').slice(0,2).join(' '),all.filter(x=>x.category===c.id).length]);return staffShell(`${staffTitle('Laporan & intelligence','Seluruh angka dihitung langsung dari data kasus unik fiktif; tidak dibuat oleh AI.',`<button class="btn" data-action="export-report">Ekspor ringkasan CSV (demo)</button>`)}<div class="dash-grid">${metric('Kasus unik',total,'Tidak menghitung pesan')}${metric('Saluran WA',channel[0][1],'Pengaduan WA')}${metric('Saluran formulir',channel[1][1],'Pengaduan form')}${metric('Terselesaikan',all.filter(c=>['RESOLVED','CLOSED'].includes(c.status)).length,'Dari seluruh kasus')}</div><div class="grid-two" style="margin-top:18px"><div class="panel">${titlebar('Volume per kategori','K01–K17 sesuai dataset demo')}${bars(by,Math.max(...by.map(x=>x[1]),1))}</div><div class="panel">${titlebar('Distribusi menurut jenjang','Kategori jenjang yang dicatat, tidak disimpulkan dari NIK')}${bars(levels,Math.max(...levels.map(x=>x[1]),1))}<div style="margin-top:28px">${titlebar('Kanal pelaporan')}${bars(channel,Math.max(...channel.map(x=>x[1]),1))}</div><div class="notice">Statistik publik atau kelompok kecil perlu pemeriksaan risiko identifikasi ulang. Nama sekolah fiktif tidak digunakan untuk ranking.</div></div></div><div class="panel" style="margin-top:18px">${titlebar('Narasi untuk pimpinan','Disusun dari penghitungan deterministik, bukan klaim AI')}<p>Dalam dataset simulasi terdapat <strong>${total} kasus unik</strong>, terdiri atas <strong>${channel[0][1]} laporan WhatsApp</strong> dan <strong>${channel[1][1]} laporan formulir</strong>. Angka ini hanya mengilustrasikan tampilan monitoring, bukan gambaran kondisi pendidikan Kabupaten Pinrang.</p><p>Untuk produksi, periode, definisi indikator, denominator, tanggal pembaruan, dan akses agregat harus ditetapkan.</p></div>`)}
function aiPage(){let eligible=casesVisible();let ran=eligible.filter(x=>x.ai).length;return staffShell(`${staffTitle('AI Assisted Triage','Gemini belum terhubung. Demo menggunakan ringkasan deterministik lokal dan mengikuti gerbang kebijakan.',`<a class="btn" href="#/dashboard/admin/settings">Pengaturan AI →</a>`)}<div class="dash-grid">${metric('Kasus dalam akses',eligible.length,'Data simulasi')}${metric('Sudah dianalisis',ran,'Hasil lokal berlabel demo')}${metric('AI produksi','NONAKTIF','Kepatuhan dan kontrak belum dipastikan','orange')}${metric('Kasus tetap jalan','YA','Fallback ke rules engine','green')}</div><div class="grid-two" style="margin-top:18px"><div class="panel">${titlebar('Simulasikan tiga fungsi AI','Klasifikasi, ringkasan, deteksi risiko dari laporan rekaan')}<div class="stack"><div class="field"><label for="ai-example">Pilih kasus</label><select id="ai-example">${eligible.slice(0,40).map(c=>`<option value="${c.id}">${esc(c.ticket)} • ${esc(cat(c.category).name)}</option>`).join('')}</select></div><button class="btn primary" data-action="ai-run-selected">Jalankan analisis demonstrasi</button><div class="notice warning">Tidak ada prompt yang dikirim ke Google. Untuk produksi, Free Tier tidak boleh dianggap boleh memproses data pribadi/sensitif; persyaratan aplikasi yang mungkin diakses anak harus dipastikan terlebih dahulu.</div></div></div><div class="panel">${titlebar('Kebijakan adapter AI')}<div class="kvs"><span>Feature flag</span><span>${state.settings.aiEnabled?'AKTIF • SIMULASI':'NONAKTIF'}</span></div><div class="kvs"><span>Gemini policy gate</span><span>${esc(state.settings.geminiGate)}</span></div><div class="kvs"><span>Output</span><span>JSON terstruktur</span></div><div class="kvs"><span>Keputusan akhir</span><span>Rules engine + manusia</span></div><div class="kvs"><span>Kuota habis / 429</span><span>Operator pusat</span></div><div class="notice success">AI bukan pemutus benar/salah, tidak dapat menutup kasus, dan tidak menentukan akses data.</div></div></div>`)}
function costCalc(c){let waCases=c.n*c.wa/100,services=waCases*c.service,paid=Math.max(0,services-c.free),meta=paid*c.serviceRate+waCases*(c.utility*c.utilityRate+c.auth*c.authRate+c.marketing*c.marketingRate),aiCases=c.n*c.aiEligible/100,ai=aiCases*c.aiCalls*(c.tin*c.pin+c.tout*c.pout)/1e6*c.fx,base=meta+ai+c.kirim+c.backend+c.storage+c.backup,buffer=base*c.reserve/100,tax=(base+buffer)*c.tax/100;return {waCases,services,paid,meta,ai,base,buffer,tax,total:base+buffer+tax,year:(base+buffer+tax)*12,perCase:(base+buffer+tax)/Math.max(1,c.n)}}
const costFields=[['n','Kasus per bulan',50,10000,50],['wa','Persentase via WA (%)',0,100,5],['service','Balasan layanan/kasus WA',0,10,1],['utility','Template utilitas/kasus',0,5,1],['auth','Template autentikasi/kasus',0,3,1],['marketing','Template marketing/kasus',0,3,1],['kirim','Langganan Kirimdev/bulan (Rp)',0,2000000,5000],['free','Kuota pesan layanan gratis',0,10000,100],['serviceRate','Tarif pesan layanan (Rp)',0,3000,.01],['utilityRate','Tarif utilitas (Rp)',0,3000,.01],['authRate','Tarif autentikasi (Rp; isi rate card)',0,3000,.01],['marketingRate','Tarif marketing (Rp)',0,3000,.01],['aiEligible','Laporan yang eligible AI (%)',0,100,5],['aiCalls','Panggilan per laporan',0,5,1],['tin','Token input/panggilan',0,15000,100],['tout','Token output/panggilan',0,10000,100],['pin','USD/juta token input',0,10,.01],['pout','USD/juta token output',0,10,.01],['fx','Kurs asumsi (Rp/USD)',10000,25000,250],['backend','Backend/bulan (Rp)',0,3000000,10000],['storage','Lampiran privat/bulan (Rp)',0,3000000,10000],['backup','Backup/bulan (Rp)',0,3000000,10000],['reserve','Cadangan (%)',0,50,1],['tax','Pajak simulasi (%)',0,30,1]];
function costs(){let c=state.cost,r=costCalc(c);return staffShell(`${staffTitle('Simulator biaya SIPAKATAU','Semua tarif adalah ASUMSI DAPAT DIEDIT dari masterplan 19 September 2026; bukan penawaran, tagihan, atau HPS.',`<div class="actions"><button class="btn" data-action="cost-reset">Reset asumsi</button><button class="btn primary" data-action="cost-export">Ekspor simulasi CSV</button></div>`)}<div class="dash-grid">${metric('Estimasi per bulan',rup(r.total),'Mencakup asumsi cadangan')}${metric('Proyeksi setahun',rup(r.year),'12 × biaya bulanan')}${metric('Biaya per tiket',rup(r.perCase),'Dibagi kasus unik')}${metric('Pesan Meta',rup(r.meta),`${fmt(r.paid)} service berbayar`,'orange')}</div><div class="grid-two" style="margin-top:19px;grid-template-columns:minmax(0,1.3fr) minmax(300px,.7fr)"><section class="panel">${titlebar('Ubah parameter simulasi','Ubah angka → hasil dihitung ulang tanpa menghubungi vendor')}<form id="cost-form" class="form-grid">${costFields.map(([key,name,min,max,step])=>`<div class="field"><label for="cost-${key}">${esc(name)}</label><input type="number" id="cost-${key}" data-cost="${key}" min="${min}" max="${max}" step="${step}" value="${escAttr(c[key])}"></div>`).join('')}</form><div class="notice warning">Harga Meta dan model AI dapat berubah. Tarif autentikasi sengaja diinisialisasi Rp0 sebagai PLACEHOLDER, bukan tarif nyata; isi rate card sebelum menyusun RAB. Free Tier Gemini hanya boleh digunakan sesuai ketentuan.</div></section><aside class="stack"><div class="panel sim-cost">${titlebar('Rincian biaya bulanan','Perhitungan mengikuti formula masterplan')}<div class="row"><span>Langganan Kirimdev</span><b>${rup(c.kirim)}</b></div><div class="row"><span>Biaya pesan Meta</span><b>${rup(r.meta)}</b></div><div class="row"><span>Biaya token AI asumsi</span><b>${rup(r.ai)}</b></div><div class="row"><span>Backend</span><b>${rup(c.backend)}</b></div><div class="row"><span>Penyimpanan privat</span><b>${rup(c.storage)}</b></div><div class="row"><span>Backup</span><b>${rup(c.backup)}</b></div><div class="row"><span>Cadangan</span><b>${rup(r.buffer)}</b></div><div class="row"><span>Pajak asumsi</span><b>${rup(r.tax)}</b></div><div class="row"><strong>TOTAL / BULAN</strong><strong style="color:#057857">${rup(r.total)}</strong></div><div class="notice">${fmt(r.waCases)} kasus WA, ${fmt(r.services)} pesan service, ${fmt(r.paid)} service berbayar. Simulasi belum memasukkan biaya pengembangan dan gaji.</div></div><div class="panel">${titlebar('Pengendalian biaya','Bukan penghentian seluruh layanan')}<div class="kvs"><span>Ambang 50/75/90/100%</span><span>${badge('Rancangan','orange')}</span></div><div class="kvs"><span>AI mencapai pagu</span><span>Matikan AI saja</span></div><div class="kvs"><span>WA cap terlewati</span><span>Batasi nonwajib</span></div><div class="kvs"><span>Backup</span><span>Tidak dihentikan</span></div></div></aside></div>`)}
function categories(){return staffShell(`${staffTitle('Master 17 kategori & routing','Setiap kategori wajib memiliki operator utama, cadangan, pemilik eskalasi, dan aturan berlaku.',`<button class="btn" data-action="export-categories">Ekspor matriks CSV</button>`)}<div class="panel">${titlebar('Matriks kategori','Status kategori K16 dan rujukan ULD membutuhkan verifikasi kelembagaan')}<div class="table-wrap"><table class="data-table"><thead><tr><th>Kode</th><th>Kategori</th><th>Operator utama</th><th>Pengganti</th><th>Status</th><th>Kelola</th></tr></thead><tbody>${state.categories.map(c=>`<tr><td><strong>${c.id}</strong></td><td><strong>${esc(c.name)}</strong><small>${esc(c.owner)}</small></td><td>${esc(c.primary)}</td><td>${esc(c.backup)}</td><td>${badge(c.enabled?'Aktif':'Nonaktif',c.enabled?'green':'orange')}</td><td><button class="btn tiny" data-action="edit-category" data-id="${c.id}">Edit</button></td></tr>`).join('')}</tbody></table></div><div id="category-edit-area"></div></div>`)}
function schools(){return staffShell(`${staffTitle('Master satuan pendidikan','Data sekolah saat ini sepenuhnya fiktif; NPSN dan satuan pendidikan nyata tidak boleh dikarang.')}<section class="panel">${titlebar('Sekolah contoh untuk pengujian','Jenjang dalam kewenangan PAUD–SMP dan nonformal/informal')}<div class="table-wrap"><table class="data-table"><thead><tr><th>ID contoh</th><th>Nama</th><th>Jenjang</th><th>Kecamatan</th><th>Verifikasi</th></tr></thead><tbody>${D.schools.map(s=>`<tr><td>${esc(s.id)}</td><td>${esc(s.name)}</td><td>${esc(s.level)}</td><td>${esc(s.district)}</td><td>${badge('Belum diverifikasi','orange')}</td></tr>`).join('')}</tbody></table></div><div class="notice">Produksi: import master terverifikasi, catat NPSN sumber serta tanggal pembaruan. Jangan mengambil atau mengubah Dapodik tanpa hak akses yang sah.</div></section>`)}
function users(){return staffShell(`${staffTitle('Akun dan pembagian peran','Ilustrasi RBAC/ABAC. Tidak ada akun pegawai atau kata sandi sesungguhnya.') }<div class="grid-two"><div class="panel">${titlebar('Peran sistem','Satu aplikasi dengan variasi kewenangan')}${D.roles.map(r=>`<div class="mini-log"><strong>${esc(r.name)}</strong><span>${esc(r.description)}</span></div>`).join('')}<div class="notice warning">Super admin teknis bukan pemegang kunci identitas pelapor. Akses kasus sensitif memerlukan petugas yang ditunjuk.</div></div><div class="panel">${titlebar('Simulasi peralihan peran','Coba setiap peran dan verifikasi layar yang muncul')}<form id="change-role-form" class="stack"><div class="field"><label for="role-change">Pilih role</label><select name="role" id="role-change">${D.roles.map(r=>`<option value="${r.id}" ${r.id===role()?'selected':''}>${esc(r.name)}</option>`).join('')}</select></div><div class="field"><label for="role-change-cat">Kategori untuk role operator</label><select name="category" id="role-change-cat">${state.categories.map(c=>`<option value="${c.id}" ${c.id===state.operatorCategory?'selected':''}>${c.id} — ${esc(c.name)}</option>`).join('')}</select></div><button class="btn primary" type="submit">Terapkan role simulasi</button></form></div></div>`)}
function settings(){return staffShell(`${staffTitle('Pengaturan sistem','Konfigurasi demonstrasi disimpan lokal. Perubahan produksi harus melalui change request.') }<div class="settings-grid">${[['aiEnabled','AI Assistant','Simulasi deterministik lokal; penggunaan Gemini produksi tetap terblokir.'],['waEnabled','WhatsApp Gateway','Sakelar simulasi tampilan. Tidak mengirim pesan.'],['alerts','Peringatan internal','Penanda keselamatan dan notifikasi internal.'],['protectedDefault','Privasi default terlindungi','Kontak tidak dibuka otomatis kepada operator.']].map(([k,t,d])=>`<label class="toggle-card"><span><strong>${t}</strong><p>${d}</p></span><input type="checkbox" aria-label="${t}" data-setting="${k}" ${state.settings[k]?'checked':''}></label>`).join('')}</div><div class="grid-two" style="margin-top:19px"><div class="panel">${titlebar('Kesiapan integrasi','Prototipe offline tidak mengandung API key')}<div class="kvs"><span>Kirimdev</span><span>${badge('Belum terhubung','orange')}</span></div><div class="kvs"><span>Gemini</span><span>${badge(state.settings.geminiGate,'orange')}</span></div><div class="kvs"><span>Firestore Jakarta</span><span>${badge('Dataset lokal','gray')}</span></div><div class="kvs"><span>Cloudflare</span><span>${badge('Aset publik saja','gray')}</span></div><div class="notice warning">Sebelum produksi: verifikasi entitas pemerintah dan Kirimdev, ketentuan Gemini untuk data/usia, penempatan seluruh pemrosesan, backup teruji, dan SOP.</div></div><div class="panel">${titlebar('Pagu biaya opsional','Uji perubahan cost guard tanpa mematikan intake')}<form class="stack" id="limits-form"><div class="field"><label for="limit-ai">Pagu AI bulanan (Rp)</label><input type="number" id="limit-ai" name="ai" min="0" value="${state.settings.limitAI}"></div><div class="field"><label for="limit-wa">Pagu WA nonwajib bulanan (Rp)</label><input type="number" id="limit-wa" name="wa" min="0" value="${state.settings.limitWA}"></div><button class="btn primary" type="submit">Simpan pagu demo</button></form><hr style="border:0;border-top:1px solid #e0e8f0;margin:20px 0"><button class="btn danger" data-action="reset-demo">Reset seluruh data simulasi</button></div></div>`)}
function backup(){return staffShell(`${staffTitle('Backup & pemulihan','Simulasi inspeksi backup; tidak membuat backup server Firestore yang sesungguhnya.') }<div class="dash-grid">${metric('Status terakhir',state.settings.backupStatus,'Bukti restore belum tersedia',state.settings.backupStatus==='LULUS SIMULASI'?'green':'orange')}${metric('Kasus data demo',state.cases.length,'Termasuk pesan dan riwayat')}${metric('Lampiran privat',0,'Tidak ada berkas nyata')}${metric('Backup produksi','BELUM ADA','Go-live ditahan','red')}</div><div class="grid-two" style="margin-top:19px"><div class="panel">${titlebar('Skenario uji pemulihan','Untuk latihan, tanpa mengunggah data ke cloud')}<p>Proses demonstrasi memeriksa jumlah kasus, riwayat, token pelacakan, dan master kategori dalam penyimpanan lokal. Ini <strong>bukan bukti pemulihan database produksi</strong>.</p><button class="btn primary" data-action="backup-test">Jalankan pemeriksaan simulasi</button><div class="notice warning">Produksi: restore Firestore, seluruh subkoleksi, identitas privat, objek lampiran, outbox, versi kebijakan, dan audit harus dibuktikan pada lingkungan terpisah.</div></div><div class="panel">${titlebar('Kriteria pemulihan')}${['Jadwal dan retensi disahkan','Arsip terenkripsi di tujuan terpisah','Integrity manifest/checksum','Restore drill tiap kuartal dan setelah perubahan besar','RPO/RTO ditentukan lewat analisis risiko','Hasil dan penanggung jawab terdokumentasi'].map(x=>`<div class="mini-log">□ ${x}</div>`).join('')}</div></div>`)}
function auditPage(){return staffShell(`${staffTitle('Audit aktivitas sistem','Jejak audit demonstrasi hanya dapat ditinjau super admin. Tidak boleh mengandung isi data pribadi.') }<div class="panel">${titlebar('Riwayat aktivitas','Catatan terbaru berada di bagian atas',`<button class="btn tiny" data-action="audit-export">Ekspor CSV</button>`)}<div class="table-wrap"><table class="data-table"><thead><tr><th>Waktu</th><th>Pelaku</th><th>Aktivitas</th></tr></thead><tbody>${state.audit.slice(0,80).map(x=>`<tr><td>${date(x.at)}</td><td>${esc(x.actor)}</td><td>${esc(x.action)}</td></tr>`).join('')}</tbody></table></div><div class="notice">Dalam implementasi, audit harus append-only, dibatasi pengaksesnya dan dilindungi dari penghapusan oleh petugas yang diaudit.</div></div>`)}
function denied(){return staffShell(`${staffTitle('Akses dibatasi','Halaman ini tidak tersedia untuk peran demo yang dipilih.')}<div class="notice alert">Peran ${esc(role())} tidak memiliki izin membuka halaman ini. Perbedaan menu hanya simulasi tampilan dan bukan keamanan produksi.</div><a class="btn" href="#/dashboard">Kembali ke ikhtisar</a>`)}
function notFound(){return publicWrap(`<div class="container page-wrap"><div class="panel" style="text-align:center"><h1>Halaman tidak ditemukan</h1><p>Periksa alamat atau kembali ke beranda SIPAKATAU.</p><a class="btn primary" href="#/">Beranda</a></div></div>`)}
function render(){let p=route();if(isStaff(p)&&!staffAccessible()){go('/login');return}let staffMap={'/dashboard':overview,'/dashboard/inbox':inbox,'/dashboard/cases':cases,'/dashboard/assignments':assignments,'/dashboard/escalations':escalations,'/dashboard/whatsapp':simulatedWhatsApp,'/dashboard/reports':reports,'/dashboard/ai':aiPage,'/dashboard/costs':costs,'/dashboard/admin/categories':categories,'/dashboard/admin/schools':schools,'/dashboard/admin/users':users,'/dashboard/admin/settings':settings,'/dashboard/admin/backup':backup,'/dashboard/admin/audit':auditPage};let publicMap={'/':home,'/pengaduan':wizard,'/lacak':tracking,'/panduan':guide,'/bantuan-anak':childHelp,'/aksesibilitas':a11y,'/privasi':priv,'/demo-whatsapp':()=>state.role?simulatedWhatsApp():publicWrap(`<div class="container page-wrap"><h1 class="page-title">Simulasi kanal WhatsApp</h1><div class="panel" style="max-width:720px"><p>Untuk mencoba webhook, pesan masuk, dan balasan simulasi, masuk sebagai Operator Pusat pada dashboard demo.</p><a class="btn primary" href="#/login">Masuk dan coba WhatsApp →</a></div></div>`),'/login':login};let body;if(p.startsWith('/dashboard/cases/'))body=navAllowed('/dashboard/cases')?caseDetail(p.split('/').pop()):denied();else if(p in staffMap)body=navAllowed(p)?staffMap[p]():denied();else body=(publicMap[p]||notFound)();app.innerHTML=body;if(ephemeral.menuOpen&&isStaff()){let sb=document.getElementById('sidebar');if(sb)sb.classList.add('open')}}
function demoAnalyze(c){if(!state.settings.aiEnabled)return toast('AI nonaktif. Hidupkan mode simulasi pada Pengaturan sebagai Super Admin.');let risks=[];if(c.priority==='CRITICAL'||c.category==='K02')risks.push('SAFETY_REVIEW');if(c.privacy==='PROTECTED')risks.push('PROTECTED_IDENTITY');if(c.category==='K17')risks.push('ACCESSIBILITY');if(['K03','K09','K11','K15'].includes(c.category))risks.push('CONFLICT_REVIEW');c.ai={suggested_category:c.category,summary:`SIMULASI LOKAL — pelapor menyatakan adanya masalah terkait ${cat(c.category).name.toLowerCase()}; belum ada pemeriksaan fakta.`,risk_flags:risks,missing_information:c.school?'[]':'Nama satuan pendidikan',requires_human_review:isSpecial(c),source:'DETERMINISTIC_DEMO_NOT_GEMINI',version:'demo-v1'};caseEvent(c,'Analisis AI simulasi disiapkan; belum diverifikasi');persist();view();toast('Hasil AI simulasi ditampilkan. Tidak ada panggilan Gemini.');}
function saveCaseFromForm(){let f=state.formDraft;let nums=state.cases.map(c=>Number(c.ticket.split('-').pop())).filter(Number.isFinite),n=Math.max(0,...nums)+1,ticket=`SIP-2026-${String(n).padStart(4,'0')}`,uncertain=f.category==='UNKNOWN',sensitive=['K02','K17'].includes(f.category)||f.emergency;let owner=uncertain||sensitive?'':cat(f.category).primary;let privacyMode=f.privacy||'PROTECTED';let c={id:id(),ticket,category:f.category,secondary:[],title:(uncertain?'Laporan belum dikategorikan':cat(f.category).name)+' — laporan form',description:f.description,school:D.schools.find(x=>x.name===f.school)?.id||null,level:f.level,privacy:privacyMode,priority:f.emergency?'CRITICAL':'NORMAL',status:sensitive||uncertain?'TRIAGE':'ASSIGNED',channel:'FORM',owner,received:now(),updated:now(),messages:[{by:'pelapor',text:f.description,at:now()}],history:[{action:'Pengaduan melalui form diterima',by:'Sistem Demo',at:now()},{action:sensitive?'Dikirim ke triase khusus':uncertain?'Kategori belum diketahui; ke operator pusat':'Disposisi berdasarkan kategori yang dipilih',by:'Rules engine demo',at:now()}],ai:null,assigneeConflict:false,tracking:`DEMO-${String(n).padStart(4,'0')}-${Math.random().toString(36).slice(2,8).toUpperCase()}`,notice:'TANDA TERIMA SIMULASI',deadline:'2026-09-30T08:00:00Z'};state.cases.unshift(c);state.lastTicket=ticket;state.step=4;audit(`${ticket}: formulir simulasi dibuat`);persist();view()}
function validateWizard(){let f=state.formDraft;ephemeral.wizardError='';if(state.step===1&&f.description.trim().length<(f.emergency?5:15)){ephemeral.wizardError='Tuliskan kronologi rekaan setidaknya '+(f.emergency?5:15)+' karakter.';return false}if(state.step===3){if(!f.ack){ephemeral.wizardError='Centang pernyataan bahwa semua data ini adalah simulasi.';return false}if(!f.adult&&!f.emergency){ephemeral.wizardError='Pengaduan reguler menggunakan pernyataan pelapor dewasa. Untuk simulasi keselamatan, tandai keadaan darurat pada langkah 2.';return false}}return true}
function simulateIncoming(text){let val=text.trim();if(!val){toast('Masukkan pesan rekaan untuk simulasi.');return}if(!state.settings.waEnabled){toast('Gateway simulasi dinonaktifkan di Pengaturan.');return}let eventId='sim-event-'+id(),n=Math.max(0,...state.cases.map(c=>Number(c.ticket.split('-').pop())||0))+1;state.eventIds.push(eventId);let c=state.cases.find(x=>x.id===state.sessionCaseId);let isNew=!c||/(laporan baru|laporan kedua|masalah lain)/i.test(val);let lower=val.toLowerCase();let guess=lower.match(/atap|plafon|bangunan|toilet|ruang kelas/)?'K10':lower.match(/disabilitas|kursi roda|aksesibilitas/)?'K17':lower.match(/pungutan|komite|bayar/)?'K03':lower.match(/perundungan|dipukul|kekerasan/)?'K02':'UNKNOWN';let critical=/runtuh|hampir jatuh|darurat|dipukul|kekerasan/i.test(lower);state.waChat.push({by:'masyarakat',text:val,at:todayTime(),eventId});let ticket;if(isNew){ticket=`SIP-2026-${String(n).padStart(4,'0')}`;let sensitive=guess==='K02'||guess==='K17'||critical;let x={id:id(),ticket,category:guess,secondary:[],title:guess==='UNKNOWN'?'Laporan WhatsApp belum terklasifikasi':cat(guess).name+' — WA',description:val,school:null,level:'UNKNOWN',privacy:'PROTECTED',priority:critical?'CRITICAL':'NORMAL',status:sensitive||guess==='UNKNOWN'?'TRIAGE':'ASSIGNED',channel:'WHATSAPP',owner:sensitive||guess==='UNKNOWN'?'':cat(guess).primary,received:now(),updated:now(),messages:[{by:'pelapor',text:val,at:now()}],history:[{action:'Webhook Kirimdev disimulasikan; event dicatat sebelum ACK',by:'Sistem Demo',at:now()},{action:'Tiket dibuat sebelum AI; routing menggunakan aturan sederhana',by:'Rules engine demo',at:now()}],ai:null,assigneeConflict:false,tracking:`DEMO-${String(n).padStart(4,'0')}-WA`,notice:'TERCATAT DI OUTBOX SIMULASI',deadline:'2026-09-30T08:00:00Z'};state.cases.unshift(x);state.sessionCaseId=x.id;c=x;audit(`${ticket}: webhook demo idempotent diterima`)}else{c.messages.push({by:'pelapor',text:val,at:now()});caseEvent(c,'Pesan tambahan diterima melalui WA');ticket=c.ticket;}const reply=`Terima kasih. Laporan ${ticket} tercatat dalam DEMO. Balasan ini tidak dikirim melalui WhatsApp asli.`;state.waChat.push({by:'sistem',text:reply,at:todayTime()});state.outbox.unshift({ticket,eventId,message:reply,state:'SIMULATED_NOT_SENT',at:now()});persist();ephemeral.chatText='';view();toast('Webhook simulasi berhasil. Nomor tiket: '+ticket)}
function downloadText(filename,body,type='text/plain;charset=utf-8'){let blob=new Blob([body],{type});let url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=filename;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}function csv(rows){return '\ufeff'+rows.map(r=>r.map(v=>'"'+String(v??'').replace(/"/g,'""')+'"').join(',')).join('\r\n')}
function transition(c,s){if(!canChange(c))return toast('Tidak mempunyai hak tindakan pada kasus ini.');const allowed={RECEIVED:['TRIAGE','ESCALATED'],TRIAGE:['ASSIGNED','NEEDS_INFO','ESCALATED'],NEEDS_INFO:['ASSIGNED','IN_PROGRESS','ESCALATED'],ASSIGNED:['IN_PROGRESS','ESCALATED'],IN_PROGRESS:['NEEDS_INFO','WAITING_EXTERNAL','RESOLUTION_REVIEW','ESCALATED'],WAITING_EXTERNAL:['RESOLUTION_REVIEW','ESCALATED'],ESCALATED:['IN_PROGRESS','RESOLUTION_REVIEW'],RESOLUTION_REVIEW:['RESOLVED','ESCALATED'],RESOLVED:['CLOSED'],CLOSED:['REOPENED'],REOPENED:['ASSIGNED','IN_PROGRESS']};if(!(allowed[c.status]||[]).includes(s))return toast('Transisi status tidak sah: '+c.status+' → '+s);if(['RESOLVED','CLOSED'].includes(s)&&!['OPERATOR_PUSAT','PERLINDUNGAN'].includes(role()))return toast('Persetujuan hasil / penutupan memerlukan pemeriksa berwenang.');if(s==='ASSIGNED'&&!c.owner)return toast('Tetapkan penanggung jawab terlebih dahulu melalui tab Penugasan.');let old=c.status;c.status=s;caseEvent(c,`${label(old)} → ${label(s)}`,role());persist();view();toast('Perubahan status simulasi berhasil dicatat.')}
function caseAssign(caseid,category){let c=state.cases.find(x=>x.id===caseid);if(!c||!['OPERATOR_PUSAT','PERLINDUNGAN'].includes(role())||!canReadCase(c))return toast('Akses disposisi ditolak.');if(!state.categories.some(x=>x.id===category))return toast('Kategori tujuan tidak dikenal.');if(c.assigneeConflict)return toast('Ditemukan konflik kepentingan; pilih pejabat alternatif secara resmi.');c.category=category;c.owner=category==='K02'?'Petugas Perlindungan':cat(category).primary;c.status='ASSIGNED';caseEvent(c,`Disposisi ke ${c.owner}; aturan routing demo`,role());persist();view();toast('Disposisi simulasi dicatat.')}
function copyValue(text){if(navigator.clipboard?.writeText){navigator.clipboard.writeText(text).then(()=>toast('Tersalin ke clipboard')).catch(()=>toast('Salin manual: '+text))}else{toast('Salin manual: '+text)}}
app.addEventListener('click',e=>{
 const cLink=e.target.closest('[data-category-link]');if(cLink){state.formDraft.category=cLink.dataset.categoryLink;state.step=0;state.lastTicket=null;persist();return}
 const tab=e.target.closest('[data-tab]');if(tab){ephemeral.pageTab=tab.dataset.tab;view();return}
 const a=e.target.closest('[data-action]');if(!a)return;let act=a.dataset.action,c=state.cases.find(x=>x.id===a.dataset.id);e.preventDefault();
 switch(act){
 case 'wizard-next':if(!validateWizard()){view();return}if(state.step===3){saveCaseFromForm();return}state.step++;persist();view();break;
 case 'wizard-prev':state.step=Math.max(0,state.step-1);ephemeral.wizardError='';persist();view();break;
 case 'new-complaint':state.formDraft=defaults().formDraft;state.step=0;state.lastTicket=null;persist();view();break;
 case 'copy-tracking':{let x=state.cases.find(z=>z.ticket===state.lastTicket);if(x)copyValue(`${x.ticket} | ${x.tracking}`);break}
 case 'track-created':{let x=state.cases.find(z=>z.ticket===state.lastTicket);ephemeral.trackResult=x;go('/lacak');break}
 case 'public-update':if(c){let text=prompt('Masukkan informasi tambahan REKAAN (bukan data nyata):');if(text&&text.trim()){c.messages.push({by:'pelapor',text:text.slice(0,700),at:now()});caseEvent(c,'Informasi tambahan melalui pelacakan');ephemeral.trackResult=c;persist();view();toast('Informasi tambahan simulasi tersimpan.')}}break;
 case 'public-appeal':if(c){let text=prompt('Alasan keberatan rekaan (jangan tuliskan identitas):');if(text&&text.trim()){let nums=state.cases.map(z=>Number(z.ticket.split('-').pop())||0),n=Math.max(...nums)+1;let appeal=structuredClone(c);appeal.id=id();appeal.ticket=`SIP-2026-${String(n).padStart(4,'0')}`;appeal.description=text;appeal.status='TRIAGE';appeal.owner='';appeal.title='Keberatan terkait '+c.ticket;appeal.history=[{action:'Tiket keberatan terkait '+c.ticket,by:'Sistem Demo',at:now()}];appeal.messages=[{by:'pelapor',text,at:now()}];appeal.tracking=`DEMO-${String(n).padStart(4,'0')}-APEL`;appeal.received=now();appeal.updated=now();appeal.parentTicket=c.ticket;state.cases.unshift(appeal);caseEvent(c,'Keberatan terkait '+appeal.ticket);ephemeral.trackResult=appeal;persist();view();toast('Tiket keberatan baru dibuat dan terhubung ke laporan asal.')}}break;
 case 'logout':state.role=null;persist();ephemeral.menuOpen=false;go('/login');break;
 case 'toggle-menu':ephemeral.menuOpen=!ephemeral.menuOpen;let sb=document.getElementById('sidebar');if(sb)sb.classList.toggle('open',ephemeral.menuOpen);break;
 case 'clear-filters':state.filter=defaults().filter;state.page=1;persist();view();break;
 case 'page-prev':state.page=Math.max(1,state.page-1);persist();view();break;
 case 'page-next':state.page++;persist();view();break;
 case 'copy-ticket':if(c)copyValue(c.ticket);break;
 case 'case-escalate':if(c)transition(c,'ESCALATED');break;
 case 'transition':if(c)transition(c,a.dataset.status);break;
 case 'open-tab':ephemeral.pageTab=a.dataset.tab;view();break;
 case 'analyze':if(c)demoAnalyze(c);break;
 case 'attachments-info':toast('Lampiran produksi: privat, 5 MB/berkas, 15 MB/kasus, validasi MIME, scan, hash dan audit.');break;
 case 'wa-canned':ephemeral.chatText=a.dataset.scenario==='safety'?'[FIKTIF] Plafon ruang kelas hampir jatuh dan anak-anak masih belajar di sana. Mohon tindakan segera.':'[FIKTIF] Seorang murid pengguna kursi roda belum memperoleh akses kelas yang memadai.';let tx=document.querySelector('#wa-text');if(tx){tx.value=ephemeral.chatText;tx.focus()}break;
 case 'wa-reset':state.waChat=[];state.sessionCaseId=null;persist();view();toast('Percakapan simulasi dikosongkan. Tiket audit tidak dihapus.');break;
 case 'wa-replay':if(!state.eventIds.length){toast('Belum ada event untuk diuji. Kirim pesan simulasi lebih dahulu.');break}toast('Event ID terakhir dikenali → replay di-ACK tanpa membuat tiket baru.');audit('Uji replay webhook: tidak membuat tiket ganda');persist();break;
 case 'wa-delivery':state.outbox[0]&&(state.outbox[0].state='SIMULATED_DELIVERED');audit('Event delivery demo diproses; tidak membuat kasus');persist();view();toast('Status pengiriman disimulasikan tanpa membuat kasus baru.');break;
 case 'ai-run-selected':{let x=state.cases.find(y=>y.id===document.getElementById('ai-example')?.value);if(x)demoAnalyze(x);break}
 case 'cost-reset':state.cost=defaults().cost;persist();view();toast('Asumsi biaya dikembalikan.');break;
 case 'cost-export':{let r=costCalc(state.cost);downloadText('SIPAKATAU_simulasi_biaya.csv',csv([['Parameter','Nilai'],...Object.entries(state.cost),['ESTIMASI_BULAN',r.total],['PROYEKSI_TAHUN',r.year],['CATATAN','Asumsi simulasi, bukan harga yang telah diverifikasi saat pembelian']]),'text/csv;charset=utf-8');break}
 case 'export-report':{let arr=state.cases;downloadText('SIPAKATAU_statistik_demo.csv',csv([['Kategori','Jumlah kasus unik'],...state.categories.map(z=>[z.id+' '+z.name,arr.filter(x=>x.category===z.id).length]),['TOTAL',arr.length]]),'text/csv;charset=utf-8');break}
 case 'export-categories':downloadText('SIPAKATAU_matriks_kategori_demo.csv',csv([['Kode','Kategori','Operator','Cadangan','Status'],...state.categories.map(z=>[z.id,z.name,z.primary,z.backup,z.enabled?'aktif':'nonaktif'])]),'text/csv;charset=utf-8');break;
 case 'edit-category':{let x=cat(a.dataset.id),area=document.getElementById('category-edit-area');if(!area)break;area.innerHTML=`<form id="category-edit" class="panel" style="margin-top:20px;background:#f6faff"><h3>Pengaturan ${esc(x.id)} — ${esc(x.name)}</h3><input type="hidden" name="id" value="${x.id}"><div class="form-grid"><div class="field"><label>Operator utama (nama fiktif)</label><input name="primary" required maxlength="90" value="${escAttr(x.primary)}"></div><div class="field"><label>Cadangan (nama fiktif)</label><input name="backup" required maxlength="90" value="${escAttr(x.backup)}"></div></div><label class="check-row" style="margin-top:15px"><input type="checkbox" name="enabled" ${x.enabled?'checked':''}>Kategori aktif untuk intake baru</label><button class="btn primary" type="submit" style="margin-top:15px">Simpan perubahan demo</button></form>`;area.scrollIntoView({behavior:'smooth',block:'nearest'});break}
 case 'audit-export':downloadText('SIPAKATAU_audit_demo.csv',csv([['Waktu','Aktor','Aktivitas'],...state.audit.map(z=>[z.at,z.actor,z.action])]),'text/csv;charset=utf-8');break;
 case 'backup-test':{let okay=state.cases.length>0&&state.cases.every(x=>x.id&&x.history?.length&&x.tracking)&&state.categories.length===17;state.settings.backupStatus=okay?'LULUS SIMULASI':'GAGAL SIMULASI';audit('Pemeriksaan backup lokal: '+state.settings.backupStatus);persist();view();toast('Pemeriksaan data lokal: '+state.settings.backupStatus+'. BUKAN restore produksi.');break}
 case 'reset-demo':{if(!confirm('Reset seluruh perubahan dan tiket DEMO yang tersimpan di browser ini?'))break;state=defaults();persist();ephemeral.pageTab='summary';ephemeral.trackResult=null;go('/login');toast('Data simulasi direset.');break}
 default:toast('Aksi ini belum didefinisikan dalam demonstrasi.');
 }
});
app.addEventListener('input',e=>{let el=e.target;if(el.matches('[data-draft]')){let k=el.dataset.draft;state.formDraft[k]=el.type==='checkbox'?el.checked:k==='child'?el.value==='true':el.value;persist()}if(el.matches('[data-cost]')){let k=el.dataset.cost;let n=Number(el.value);if(Number.isFinite(n))state.cost[k]=n;persist();/* perbarui hasil setelah change/blur agar fokus angka tidak terputus */}});
app.addEventListener('change',e=>{let el=e.target;if(el.matches('[data-draft]')){let k=el.dataset.draft;state.formDraft[k]=el.type==='checkbox'?el.checked:k==='child'?el.value==='true':el.value;if(k==='privacy'&&el.value==='NO_ID_FORM'){state.formDraft.name='';state.formDraft.wa=''}persist();if(['privacy','child'].includes(k))view()}if(el.matches('[data-filter]')){state.filter[el.dataset.filter]=el.value;state.page=1;persist();view()}if(el.matches('[data-setting]')){state.settings[el.dataset.setting]=el.checked;audit('Pengaturan simulasi '+el.dataset.setting+' = '+el.checked,role());persist();view();toast('Pengaturan hanya berlaku pada demo.')}if(el.matches('[data-cost]')){state.cost[el.dataset.cost]=Number(el.value)||0;persist();view()}});
app.addEventListener('submit',e=>{const f=e.target;e.preventDefault();let form=new FormData(f);if(f.id==='role-login'){state.role=form.get('role');state.operatorCategory=form.get('category')||'K03';ephemeral.menuOpen=false;persist();go('/dashboard');toast('Mode simulasi: '+state.role);return}if(f.id==='change-role-form'){state.role=form.get('role');state.operatorCategory=form.get('category')||'K03';audit('Peran demo diubah ke '+state.role);persist();go('/dashboard');view();return}if(f.id==='tracking-form'){let ticket=String(form.get('ticket')||'').trim().toUpperCase(),secret=String(form.get('secret')||'').trim();let c=state.cases.find(x=>x.ticket===ticket&&x.tracking===secret);ephemeral.trackResult=c||null;view();toast(c?'Status ditemukan. Hanya informasi aman yang ditampilkan.':'Tiket atau kode tidak cocok. Tidak ada informasi privat ditampilkan.');return}if(f.id==='wa-form'){simulateIncoming(String(form.get('text')||''));return}if(f.id==='assign-form'){caseAssign(String(form.get('caseid')),String(form.get('category')));return}if(f.id==='reply-form'){let c=state.cases.find(x=>x.id===form.get('caseid'));if(!c||!canChange(c))return toast('Akses balasan ditolak.');let text=String(form.get('message')||'').trim();if(text.length<5)return toast('Tanggapan terlalu singkat.');c.messages.push({by:'petugas',text,at:now()});caseEvent(c,'Tanggapan dicatat pada outbox demo',role());state.outbox.unshift({ticket:c.ticket,message:text,state:'SIMULATED_NOT_SENT',at:now()});persist();view();toast('Balasan simulasi tersimpan, tidak dikirim ke WA.');return}if(f.id==='category-edit'){let c=state.categories.find(x=>x.id===form.get('id'));if(!c)return toast('Kategori tidak ada.');if(form.get('primary')===form.get('backup'))return toast('Operator utama dan cadangan tidak boleh sama.');c.primary=String(form.get('primary')).slice(0,90);c.backup=String(form.get('backup')).slice(0,90);c.enabled=form.get('enabled')==='on';audit('Konfigurasi kategori '+c.id+' diperbarui',role());persist();view();toast('Master kategori disimpan untuk demo; perubahan membutuhkan persetujuan pada produksi.');return}if(f.id==='limits-form'){state.settings.limitAI=Number(form.get('ai'))||0;state.settings.limitWA=Number(form.get('wa'))||0;audit('Pagu demo diperbarui',role());persist();view();toast('Pagu biaya simulasi tersimpan.');return}});
window.addEventListener('hashchange',()=>{ephemeral.menuOpen=false;ephemeral.pageTab='summary';render();window.scrollTo(0,0)});
window.SIPAKATAU_TEST={reset(){state=defaults();persist();render()},getState:()=>state,calculate:costCalc,categories:()=>state.categories,canBrowse,transition};
function applyV21Visuals(){
 const path=route();
 const visualMap=path==='/'?['assets/illustrations/01_konsultasi_pendidikan.webp','Ilustrasi konsultasi pendidikan']:path==='/pengaduan'?['assets/illustrations/02_form_dengan_voice.webp','Ilustrasi formulir dengan bantuan suara']:path==='/bantuan-anak'?['assets/illustrations/03_sekolah_inklusif.webp','Ilustrasi sekolah inklusif']:['assets/illustrations/04_routing_pengaduan.webp','Ilustrasi alur routing pengaduan'];
 const target=document.querySelector('.hero-visual,.panel');
 if(target&&!target.querySelector('.v21-illustration')){const img=document.createElement('img');img.className='v21-illustration';img.src=visualMap[0];img.alt=visualMap[1];target.prepend(img);if(window.SIPAudioGuide&&path!=='/dashboard'){const b=document.createElement('button');b.type='button';b.className='btn audio-guide-button';b.textContent='🔊 Dengarkan panduan';b.addEventListener('click',()=>{const key=path==='/'?'publicIntro':path==='/pengaduan'?'formStep':path==='/lacak'?'tracking':'privacy';const result=window.SIPAudioGuide.speak(key);if(result==='NO_INDONESIAN_VOICE'||result==='UNSUPPORTED')b.textContent='📖 Baca panduan teks';else b.textContent=result==='SPEAKING'?'⏹ Hentikan panduan':'🔊 Dengarkan panduan'});target.append(b)}}
}
const baseRender=render; render=()=>{baseRender();applyV21Visuals()};
render();
})();
